window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["NEH"]={"book":"NEH","editions":{"fin-biblia1776":[[1,1,"Nämät ovat Nehemian Hakalian pojan teot. Tapahtui Kislevin kuulla, kahdentenakymmenentenä vuonna, kuin minä olin Susanin linnassa,","Nämät ovat Nehemian Hakalian pojan teot. Tapahtui Kislevin kuulla, kahdentenakymmenentenä vuonna, kuin minä olin Susanin linnassa,"],[1,2,"Niin tuli Hanani, yksi veljistäni muutamain Juudan miesten kanssa; ja minä kysyin heiltä Juudalaisista, jotka vankeudesta jääneet ja päässeet olivat, ja Jerusalemin menoista.","Niin tuli Hanani, yksi veljistäni muutamain Juudan miesten kanssa; ja minä kysyin heiltä Juudalaisista, jotka vankeudesta jääneet ja päässeet olivat, ja Jerusalemin menoista."],[1,3,"Ja he sanoivat minulle: ne, jotka jäljelle jääneet ovat vankeudesta, ovat siellä maassa suuressa onnettomuudessa ja häpiässä; Jerusalemin muurit ovat jaotetut ja sen portit tulella poltetut.","Ja he sanoivat minulle: ne, jotka jäljelle jääneet ovat vankeudesta, ovat siellä maassa suuressa onnettomuudessa ja häpiässä; Jerusalemin muurit ovat jaotetut ja sen portit tulella poltetut."],[1,4,"Kuin minä senkaltaiset sanat kuulin, niin minä istuin ja murehdin muutamat päivät, paastosin ja rukoilin taivaan Jumalan edessä,","Kuin minä senkaltaiset sanat kuulin, niin minä istuin ja murehdin muutamat päivät, paastosin ja rukoilin taivaan Jumalan edessä,"],[1,5,"Ja sanoin: Oi Herra, taivaan Jumala, suuri ja peljättävä Jumala, joka pidät liiton ja laupiuden niille, jotka sinua rakastavat ja pitävät sinun käskys!","Ja sanoin: Oi Herra, taivaan Jumala, suuri ja peljättävä Jumala, joka pidät liiton ja laupiuden niille, jotka sinua rakastavat ja pitävät sinun käskys!"],[1,6,"Anna korvas kuulla ja silmäs avoinna olla, kuulemaan palvelias rukousta, kuin minä nyt rukoilen sinun edessäs yöt ja päivät palveliais Israelin lasten edessä; ja minä tunnustan Israelin lasten synnit, jotka me olemme tehneet sinua vastaan; ja minä ja minun isäni huone olemme syntiä tehneet.","Anna korvas kuulla ja silmäs avoinna olla, kuulemaan palvelias rukousta, kuin minä nyt rukoilen sinun edessäs yöt ja päivät palveliais Israelin lasten edessä; ja minä tunnustan Israelin lasten synnit, jotka me olemme tehneet sinua vastaan; ja minä ja minun isäni huone olemme syntiä tehneet."],[1,7,"Me olemme kovin turmelleet itsemme, ettemme ole pitäneet sinun käskyjäs, säätyjäs ja oikeuttas, joitas olet palvelialles Mosekselle käskenyt.","Me olemme kovin turmelleet itsemme, ettemme ole pitäneet sinun käskyjäs, säätyjäs ja oikeuttas, joitas olet palvelialles Mosekselle käskenyt."],[1,8,"Mutta muista kuitenkin sitä sanaa, jonka sinä käskit Mosekselle palvelialles ja sanoit: koska te rikotte, niin minä hajoitan teidät kansain sekaan.","Mutta muista kuitenkin sitä sanaa, jonka sinä käskit Mosekselle palvelialles ja sanoit: koska te rikotte, niin minä hajoitan teidät kansain sekaan."],[1,9,"Mutta jos te palajatte minun tyköni, ja pidätte minun käskyni ja teette ne: ja jos te ajetaan hamaan taivaan ääriin, niin minä sieltäkin teidät kokoon ja vien siihen paikkaan, jonka minä olen valinnut nimeni asumasiaksi.","Mutta jos te palajatte minun tyköni, ja pidätte minun käskyni ja teette ne: ja jos te ajetaan hamaan taivaan ääriin, niin minä sieltäkin teidät kokoon ja vien siihen paikkaan, jonka minä olen valinnut nimeni asumasiaksi."],[1,10,"He ovat kuitenkin sinun palvelias ja sinun kansas, jotkas vapahdit suurella voimallas ja väkevällä kädelläs.","He ovat kuitenkin sinun palvelias ja sinun kansas, jotkas vapahdit suurella voimallas ja väkevällä kädelläs."],[1,11,"O Herra! olkoon korvas avoinna palvelias rukoukseen ja sinun palveliais rukouksiin, jotka pyytävät peljätä sinun nimeäs, ja anna palvelias tänäpänä menestyä, ja anna heille armo tämän miehen edessä! Sillä minä olin kuninkaan juomanlaskia.","O Herra! olkoon korvas avoinna palvelias rukoukseen ja sinun palveliais rukouksiin, jotka pyytävät peljätä sinun nimeäs, ja anna palvelias tänäpänä menestyä, ja anna heille armo tämän miehen edessä! Sillä minä olin kuninkaan juomanlaskia."],[2,1,"Ja tapahtui kuningas Artahsastan kahdentenakymmenentenä vuonna, Nisanin kuulla, kuin viina oli hänen edessänsä, ja että minä otin viinan ja annoin kuninkaalle; mutta en minä ollut (ennen) murheellinen hänen edessänsä.","Ja tapahtui kuningas Artahsastan kahdentenakymmenentenä vuonna, Nisanin kuulla, kuin viina oli hänen edessänsä, ja että minä otin viinan ja annoin kuninkaalle; mutta en minä ollut (ennen) murheellinen hänen edessänsä."],[2,2,"Niin kuningas sanoi minulle: miksi niin pahoin katsot, ja et kuitenkaan kipeä ole? Ei se muu ole, mutta murhe on sinun sydämessäs. Ja minä pelkäsin sangen kovin.","Niin kuningas sanoi minulle: miksi niin pahoin katsot, ja et kuitenkaan kipeä ole? Ei se muu ole, mutta murhe on sinun sydämessäs. Ja minä pelkäsin sangen kovin."],[2,3,"Niin minä sanoin kuninkaalle: eläköön kuningas ijankaikkisesti! Eikö kasvoni mahda olla murheelliset, kuin se kaupunki, jossa isäni hautaushuone on, kylmillä on, ja sen portit ovat tulella kulutetut?","Niin minä sanoin kuninkaalle: eläköön kuningas ijankaikkisesti! Eikö kasvoni mahda olla murheelliset, kuin se kaupunki, jossa isäni hautaushuone on, kylmillä on, ja sen portit ovat tulella kulutetut?"],[2,4,"Niin sanoi kuningas minulle: mitäs siis anot? Niin minä rukoilin Taivaan Jumalaa,","Niin sanoi kuningas minulle: mitäs siis anot? Niin minä rukoilin Taivaan Jumalaa,"],[2,5,"Ja sanoin kuninkaalle: jos kelpaa kuninkaalle, ja jos palvelias on sinun edessäs kelvollinen: ettäs lähettäisit minut Juudaan, isäni hautauskaupunkiin, rakentamaan sitä.","Ja sanoin kuninkaalle: jos kelpaa kuninkaalle, ja jos palvelias on sinun edessäs kelvollinen: ettäs lähettäisit minut Juudaan, isäni hautauskaupunkiin, rakentamaan sitä."],[2,6,"Niin sanoi kuningas minulle ja kuningatar, joka hänen vieressänsä istui: kuinka kauvan sinä matkassa olet, ja koska sinä palajat? Ja se kelpasi kuninkaalle, ja hän lähetti minun, kuin minä ajan hänelle määrännyt olin.","Niin sanoi kuningas minulle ja kuningatar, joka hänen vieressänsä istui: kuinka kauvan sinä matkassa olet, ja koska sinä palajat? Ja se kelpasi kuninkaalle, ja hän lähetti minun, kuin minä ajan hänelle määrännyt olin."],[2,7,"Ja minä sanoin kuninkaalle: jos kuninkaan tahto niin on, niin annettakoon minulle kirjat päämiesten tykö toisella puolella virtaa, että he vievät minun ylitse, siihenasti kuin minä tulen Juudaan,","Ja minä sanoin kuninkaalle: jos kuninkaan tahto niin on, niin annettakoon minulle kirjat päämiesten tykö toisella puolella virtaa, että he vievät minun ylitse, siihenasti kuin minä tulen Juudaan,"],[2,8,"Ja kirjan Asaphille, joka on kuninkaan metsänvartia, että hän lähettää minulle hirsiä salin porttein vuolteiksi, kuin on huoneen tykönä, ja kaupungin muuriin ja siihen huoneesen, johon minä menen. Ja kuningas antoi minulle niinkuin Jumalani hyvä käsi oli minun ylitseni.","Ja kirjan Asaphille, joka on kuninkaan metsänvartia, että hän lähettää minulle hirsiä salin porttein vuolteiksi, kuin on huoneen tykönä, ja kaupungin muuriin ja siihen huoneesen, johon minä menen. Ja kuningas antoi minulle niinkuin Jumalani hyvä käsi oli minun ylitseni."],[2,9,"Ja kuin minä tulin sille puolelle virtaa päämiesten tykö, niin minä annoin heille kuninkaan kirjan; kuningas lähetti myös minun kanssani sodanpäämiehiä ja hevosmiehiä.","Ja kuin minä tulin sille puolelle virtaa päämiesten tykö, niin minä annoin heille kuninkaan kirjan; kuningas lähetti myös minun kanssani sodanpäämiehiä ja hevosmiehiä."],[2,10,"Mutta kuin Sanballat Horonilainen ja palvelia Tobia Ammonilainen sen kuulivat, panivat he pahaksensa sangen kovin, että joku ihminen tuli, joka Israelin lasten parasta katsoi.","Mutta kuin Sanballat Horonilainen ja palvelia Tobia Ammonilainen sen kuulivat, panivat he pahaksensa sangen kovin, että joku ihminen tuli, joka Israelin lasten parasta katsoi."],[2,11,"Ja kuin minä tulin Jerusalemiin ja olin siellä ollut kolme päivää,","Ja kuin minä tulin Jerusalemiin ja olin siellä ollut kolme päivää,"],[2,12,"Nousin minä yöllä ja vähä väkeä minun kanssani; sillä en minä sanonut kellenkään, mitä minun Jumalani oli antanut sydämeeni, tehdäkseni Jerusalemissa; ja ei minulla ollut yhtään juhtaa myötäni, muuta kuin se, jonka päällä minä istuin.","Nousin minä yöllä ja vähä väkeä minun kanssani; sillä en minä sanonut kellenkään, mitä minun Jumalani oli antanut sydämeeni, tehdäkseni Jerusalemissa; ja ei minulla ollut yhtään juhtaa myötäni, muuta kuin se, jonka päällä minä istuin."],[2,13,"Ja minä ajoin Laaksoportista ulos yöllä, Kärmelähteen kohdalle Sontaporttiin asti ja katselin Jerusalemin muureja, jotka olivat jaotetut, ja portteja, jotka olivat tulella kulutetut.","Ja minä ajoin Laaksoportista ulos yöllä, Kärmelähteen kohdalle Sontaporttiin asti ja katselin Jerusalemin muureja, jotka olivat jaotetut, ja portteja, jotka olivat tulella kulutetut."],[2,14,"Ja minä menin vielä Lähdeporttiin ja Kuninkaan vesilammin tykö; ja ei ollut sielä siaa, että minun juhtani sai käydä minun allani.","Ja minä menin vielä Lähdeporttiin ja Kuninkaan vesilammin tykö; ja ei ollut sielä siaa, että minun juhtani sai käydä minun allani."],[2,15,"Kuitenkin menin minä yöllä ojaa myöten ja koettelin muuria; sitte palasin minä ja tulin jälleen Laaksoporttiin.","Kuitenkin menin minä yöllä ojaa myöten ja koettelin muuria; sitte palasin minä ja tulin jälleen Laaksoporttiin."],[2,16,"Ja ei ylimmäiset tietäneet, kuhunka minä menin, taikka mitä minä tein; sillä en minä vielä siihenasti ilmoittanut mitään kellenkään, Juudalaisille eikä papeille, ylimmäisille taikka esivallalle, ja muille työn tekiöille.","Ja ei ylimmäiset tietäneet, kuhunka minä menin, taikka mitä minä tein; sillä en minä vielä siihenasti ilmoittanut mitään kellenkään, Juudalaisille eikä papeille, ylimmäisille taikka esivallalle, ja muille työn tekiöille."],[2,17,"Ja minä sanoin heille: te näette tämän onnettomuuden, jossa me olemme, että Jerusalem on autiona, ja sen portit ovat tulella kulutetut: tulkaat ja rakentakaamme Jerusalemin muurit, ettemme enää häpiänä olisi.","Ja minä sanoin heille: te näette tämän onnettomuuden, jossa me olemme, että Jerusalem on autiona, ja sen portit ovat tulella kulutetut: tulkaat ja rakentakaamme Jerusalemin muurit, ettemme enää häpiänä olisi."],[2,18,"Ja minä ilmoitin heille minun Jumalani käden, joka oli hyvä minun päälläni, ja myös kuninkaan sanat, jotka hän sanoi minulle. Ja he sanoivat: nouskaamme siis ja rakentakaamme. Ja heidän kätensä vahvistuivat hyvyyteen.","Ja minä ilmoitin heille minun Jumalani käden, joka oli hyvä minun päälläni, ja myös kuninkaan sanat, jotka hän sanoi minulle. Ja he sanoivat: nouskaamme siis ja rakentakaamme. Ja heidän kätensä vahvistuivat hyvyyteen."],[2,19,"Mutta kun Sanballat Horonilainen, ja palvelia Tobia Ammonilainen, ja Gesem Arabialainen sen kuulivat, häpäisivät he meitä ja katsoivat meidät ylön ja sanoivat: mikä se on, jota te teette? tahdotteko te luopua jälleen kuninkaasta?","Mutta kun Sanballat Horonilainen, ja palvelia Tobia Ammonilainen, ja Gesem Arabialainen sen kuulivat, häpäisivät he meitä ja katsoivat meidät ylön ja sanoivat: mikä se on, jota te teette? tahdotteko te luopua jälleen kuninkaasta?"],[2,20,"Niin minä vastasin heitä ja sanoin heille: taivaan Jumala antaa meille menestyksen, sillä me hänen palveliansa olemme valmistaneet itsemme ja rakennamme; mutta ei teillä ole yhtäkään osaa eli oikeutta, taikka muistoa Jerusalemissa.","Niin minä vastasin heitä ja sanoin heille: taivaan Jumala antaa meille menestyksen, sillä me hänen palveliansa olemme valmistaneet itsemme ja rakennamme; mutta ei teillä ole yhtäkään osaa eli oikeutta, taikka muistoa Jerusalemissa."],[3,1,"Ja Eljasib, ylimmäinen pappi, nousi pappein veljeinsä kanssa, rakensivat Lammasportin ja pyhittivät sen, ja panivat siihen ovet; ja he pyhittivät sen Mean torniin asti, hamaan Hananeelin torniin saakka.","Ja Eljasib, ylimmäinen pappi, nousi pappein veljeinsä kanssa, rakensivat Lammasportin ja pyhittivät sen, ja panivat siihen ovet; ja he pyhittivät sen Mean torniin asti, hamaan Hananeelin torniin saakka."],[3,2,"Ja Jerihon miehet rakensivat hänen vieressänsä, ja Sakkur Imrin poika rakensi hänen vieressänsä.","Ja Jerihon miehet rakensivat hänen vieressänsä, ja Sakkur Imrin poika rakensi hänen vieressänsä."],[3,3,"Mutta Senaan lapset rakensivat Kalaportin, ja kattivat sen, ja panivat siihen ovet, lukot ja teljet.","Mutta Senaan lapset rakensivat Kalaportin, ja kattivat sen, ja panivat siihen ovet, lukot ja teljet."],[3,4,"Ja Meremot Urian poika, Hakkotsin pojan, rakensi heidän vieressänsä, ja Mesullam Berekian poika, Mesesabelin pojan, rakensi heidän vieressänsä; Zadok Baenan poika rakensi heidän vieressänsä.","Ja Meremot Urian poika, Hakkotsin pojan, rakensi heidän vieressänsä, ja Mesullam Berekian poika, Mesesabelin pojan, rakensi heidän vieressänsä; Zadok Baenan poika rakensi heidän vieressänsä."],[3,5,"Niiden tykönä rakensivat Tekoan miehet; mutta heidän sankarinsa ei kääntäneet kaulaansa Herransa palvelukseen.","Niiden tykönä rakensivat Tekoan miehet; mutta heidän sankarinsa ei kääntäneet kaulaansa Herransa palvelukseen."],[3,6,"Vanhan portin rakensi Jojada Passean poika ja Mesullam Besodian poika, ja kattivat sen, ja panivat siihen ovet, lukot ja teljet.","Vanhan portin rakensi Jojada Passean poika ja Mesullam Besodian poika, ja kattivat sen, ja panivat siihen ovet, lukot ja teljet."],[3,7,"Melatia Gibeonilainen ja Jadon Meronotilainen rakensi heidän vieressänsä, Gibeonin ja Mitspan miehet, päämiehen istuimen tykönä, sillä puolella virtaa.","Melatia Gibeonilainen ja Jadon Meronotilainen rakensi heidän vieressänsä, Gibeonin ja Mitspan miehet, päämiehen istuimen tykönä, sillä puolella virtaa."],[3,8,"Hänen vieressänsä rakensi Ussiel Harhakan kultasepän poika; hänen vieressänsä rakensi Hanania yrtteinmyyjän poika; ja he rakensivat Jerusalemia leviään muuriin asti.","Hänen vieressänsä rakensi Ussiel Harhakan kultasepän poika; hänen vieressänsä rakensi Hanania yrtteinmyyjän poika; ja he rakensivat Jerusalemia leviään muuriin asti."],[3,9,"Hänen vieressänsä rakensi Rephaja Hurin poika, puolen Jerusalemin päämies.","Hänen vieressänsä rakensi Rephaja Hurin poika, puolen Jerusalemin päämies."],[3,10,"Heidän vieressänsä rakensi Jedaja Harumaphin poika, huoneensa kohdalla; hänen vieressänsä rakensi Hattus, Hasabnejan poika.","Heidän vieressänsä rakensi Jedaja Harumaphin poika, huoneensa kohdalla; hänen vieressänsä rakensi Hattus, Hasabnejan poika."],[3,11,"Mutta Malkia Harimin poika ja Hasub Pahatmoabin poika rakensivat toista kulmaa, niin myös Pätsitornin.","Mutta Malkia Harimin poika ja Hasub Pahatmoabin poika rakensivat toista kulmaa, niin myös Pätsitornin."],[3,12,"Hänen vieressänsä rakensi Sallum Haloeksen poika, puolen Jerusalemin päämies: hän itse ja hänen tyttärensä.","Hänen vieressänsä rakensi Sallum Haloeksen poika, puolen Jerusalemin päämies: hän itse ja hänen tyttärensä."],[3,13,"Laaksoportin rakensi Hanun ja Sanoan asujamet; ne rakensivat sen ja panivat siihen ovet, lukot ja teljet, ja tuhannen kyynärää muuria Sontaporttiin asti.","Laaksoportin rakensi Hanun ja Sanoan asujamet; ne rakensivat sen ja panivat siihen ovet, lukot ja teljet, ja tuhannen kyynärää muuria Sontaporttiin asti."],[3,14,"Mutta Malkia Rekabin poika, viinamäen kulmakunnan päämies, rakensi Sontaportin, hän rakensi sen ja pani siihen ovet, lukot ja teljet.","Mutta Malkia Rekabin poika, viinamäen kulmakunnan päämies, rakensi Sontaportin, hän rakensi sen ja pani siihen ovet, lukot ja teljet."],[3,15,"Mutta Lähdeportin rakensi Sallun Kolhosen poika, Mitspan kulmakunnan päämies; hän rakensi ja katti sen, ja pani siihen ovet, lukot ja teljet; niin myös Selan lammin muurin kuninkaan yrttitarhan tykönä, niihin astuimiin asti, jotka tulevat alas Davidin kaupungista.","Mutta Lähdeportin rakensi Sallun Kolhosen poika, Mitspan kulmakunnan päämies; hän rakensi ja katti sen, ja pani siihen ovet, lukot ja teljet; niin myös Selan lammin muurin kuninkaan yrttitarhan tykönä, niihin astuimiin asti, jotka tulevat alas Davidin kaupungista."],[3,16,"Hänen vieressänsä rakensi Nehemia Asbukin poika, puolen Betsuurin päämies, aina Davidin hautain kohdalle, ja kaivettuun lammikkoon asti väkeväin huoneeseen asti.","Hänen vieressänsä rakensi Nehemia Asbukin poika, puolen Betsuurin päämies, aina Davidin hautain kohdalle, ja kaivettuun lammikkoon asti väkeväin huoneeseen asti."],[3,17,"Häntä likimpänä rakensivat Leviläiset, Rehum Banin poika; hänen vieressänsä rakensi Hasabia, puolen Kegilan päämies kulmakuntansa puolesta.","Häntä likimpänä rakensivat Leviläiset, Rehum Banin poika; hänen vieressänsä rakensi Hasabia, puolen Kegilan päämies kulmakuntansa puolesta."],[3,18,"Häntä likimpänä rakensivat heidän veljensä Bavai Hanadadin poika, toisen puolen Kegilan päämies.","Häntä likimpänä rakensivat heidän veljensä Bavai Hanadadin poika, toisen puolen Kegilan päämies."],[3,19,"Hänen vieressänsä rakensi Eser Jesuan poika, Mitspan päämies, toisen osan siinä kulmassa, asehuoneen puolessa.","Hänen vieressänsä rakensi Eser Jesuan poika, Mitspan päämies, toisen osan siinä kulmassa, asehuoneen puolessa."],[3,20,"Häntä likinnä rakensi Baruk Sabbain poika kiivaasti toisen osan kulmasta Eljasibin ylimmäisen papin huoneen oveen asti.","Häntä likinnä rakensi Baruk Sabbain poika kiivaasti toisen osan kulmasta Eljasibin ylimmäisen papin huoneen oveen asti."],[3,21,"Häntä likinnä rakensi Meremot Urian poika, Hakkotsin pojan, toisen osan, Eljasibin huoneen ovesta Eljasibin huoneen loppuun asti.","Häntä likinnä rakensi Meremot Urian poika, Hakkotsin pojan, toisen osan, Eljasibin huoneen ovesta Eljasibin huoneen loppuun asti."],[3,22,"Ja hänen jälkeensä rakensivat papit, miehet lakeudelta.","Ja hänen jälkeensä rakensivat papit, miehet lakeudelta."],[3,23,"Heidän jälkeensä rakensi Benjamin ja Hassub oman huoneensa kohdalla; heidän perässänsä rakensi Asaria Maesejan poika, Ananian pojan, huoneensa tykönä.","Heidän jälkeensä rakensi Benjamin ja Hassub oman huoneensa kohdalla; heidän perässänsä rakensi Asaria Maesejan poika, Ananian pojan, huoneensa tykönä."],[3,24,"Hänen jälkeensä rakensi Binnui Henadadin poika, toisen osan, Asarian huoneesta niin loukkaasen ja hamaan kulmaan asti.","Hänen jälkeensä rakensi Binnui Henadadin poika, toisen osan, Asarian huoneesta niin loukkaasen ja hamaan kulmaan asti."],[3,25,"Palal Usain poika loukasta vastaan ja tornia, joka menee kuninkaan ylisestä huoneesta, joka oli vankikartanon tykönä; hänen jälkeensä Pedaja Paroksen poika.","Palal Usain poika loukasta vastaan ja tornia, joka menee kuninkaan ylisestä huoneesta, joka oli vankikartanon tykönä; hänen jälkeensä Pedaja Paroksen poika."],[3,26,"Mutta Netinimit asuivat Ophelin tykönä Vesiporttiin asti itään päin, josta torni käy ulos.","Mutta Netinimit asuivat Ophelin tykönä Vesiporttiin asti itään päin, josta torni käy ulos."],[3,27,"Sitälikin rakensivat Tekoalaiset toisen osan, isoa tornia päin, kuin näkyy ulos, Opelin muuriin asti,","Sitälikin rakensivat Tekoalaiset toisen osan, isoa tornia päin, kuin näkyy ulos, Opelin muuriin asti,"],[3,28,"Mutta Hevosportin yläpuolelta rakensivat papit, jokainen huoneensa kohdalla.","Mutta Hevosportin yläpuolelta rakensivat papit, jokainen huoneensa kohdalla."],[3,29,"Heidän jälissänsä rakensi Zadok Immerin poika, huoneensa kohdalla; hänen jälissänsä rakensi Semaja Sekanian poika, Itäportin vartia.","Heidän jälissänsä rakensi Zadok Immerin poika, huoneensa kohdalla; hänen jälissänsä rakensi Semaja Sekanian poika, Itäportin vartia."],[3,30,"Hänen jälissänsä rakensi Hananian Selemian poika, ja Hanun kuudes Salaphin poika, toisen osan; hänen jälissänsä rakensi Mesullam Berekian poika, makaushuoneensa kohdalla.","Hänen jälissänsä rakensi Hananian Selemian poika, ja Hanun kuudes Salaphin poika, toisen osan; hänen jälissänsä rakensi Mesullam Berekian poika, makaushuoneensa kohdalla."],[3,31,"Hänen jälissänsä rakensi Malkia kultasepän poika, Netinimein ja kauppamiesten huoneesen asti, Käräjäportin kohdalla, hamaan Kulmasaliin saakka.","Hänen jälissänsä rakensi Malkia kultasepän poika, Netinimein ja kauppamiesten huoneesen asti, Käräjäportin kohdalla, hamaan Kulmasaliin saakka."],[3,32,"Kultasepät ja kauppamiehet rakensivat Kulmasalin välillä ja Lammasporttiin asti.","Kultasepät ja kauppamiehet rakensivat Kulmasalin välillä ja Lammasporttiin asti."],[4,1,"Kuin Sanballat kuuli meidän muuria rakentavan, syttyi hän vihaan ja närkästyi sangen suuresti, ja häpäisi Juudalaisia,","Kuin Sanballat kuuli meidän muuria rakentavan, syttyi hän vihaan ja närkästyi sangen suuresti, ja häpäisi Juudalaisia,"],[4,2,"Ja puhui veljeinsä ja voimallisten edessä Samariassa ja sanoi: mitä nämät voimattomat Juudalaiset tekevät? pitääkö heille niin sallittaman? pitääkö heidän uhraaman? pitääkö heidän sen täyttämän yhtenä päivänä? pitääkö heidän kiviä eläväksi tekemän, jotka ovat tuhkaläjä ja palaneet?","Ja puhui veljeinsä ja voimallisten edessä Samariassa ja sanoi: mitä nämät voimattomat Juudalaiset tekevät? pitääkö heille niin sallittaman? pitääkö heidän uhraaman? pitääkö heidän sen täyttämän yhtenä päivänä? pitääkö heidän kiviä eläväksi tekemän, jotka ovat tuhkaläjä ja palaneet?"],[4,3,"Ja Tobia Ammonilainen sanoi hänen jälkeensä: rakentakoot vapaasti; jos ketut sinne menisivät, niin he kyllä jaottaisivat heidän kivimuurinsa.","Ja Tobia Ammonilainen sanoi hänen jälkeensä: rakentakoot vapaasti; jos ketut sinne menisivät, niin he kyllä jaottaisivat heidän kivimuurinsa."],[4,4,"Kuule meidän Jumalamme, kuinka me olemme katsotut ylön, ja käännä heidän häväistyksensä heidän päänsä päälle, ja saata heitä häpiään vankeuden maassa.","Kuule meidän Jumalamme, kuinka me olemme katsotut ylön, ja käännä heidän häväistyksensä heidän päänsä päälle, ja saata heitä häpiään vankeuden maassa."],[4,5,"Älä peitä heidän pahoja tekojansa ja älä pyyhi heidän syntiänsä kasvois edestä; sillä he ovat vihan matkaan saattaneet, rakentajain läsnäollessa.","Älä peitä heidän pahoja tekojansa ja älä pyyhi heidän syntiänsä kasvois edestä; sillä he ovat vihan matkaan saattaneet, rakentajain läsnäollessa."],[4,6,"Mutta me rakensimme muurin ja panimme hänen kaiketi yhteen hamaan puoliväliin asti; ja kansa sai sydämen työtä tehdäksensä.","Mutta me rakensimme muurin ja panimme hänen kaiketi yhteen hamaan puoliväliin asti; ja kansa sai sydämen työtä tehdäksensä."],[4,7,"Kuin Sanballat ja Tobia ja Arabialaiset ja Ammonilaiset ja Asdodilaiset kuulivat Jerusalemin muurit korotetuksi, ja ruvetuksi haljenneita parantamaan, vihastuivat he sangen suuresti.","Kuin Sanballat ja Tobia ja Arabialaiset ja Ammonilaiset ja Asdodilaiset kuulivat Jerusalemin muurit korotetuksi, ja ruvetuksi haljenneita parantamaan, vihastuivat he sangen suuresti."],[4,8,"Ja he kaikki tekivät liiton keskenänsä tullaksensa sotimaan Jerusalemia vastaan, ja tekemään heille kapinaa.","Ja he kaikki tekivät liiton keskenänsä tullaksensa sotimaan Jerusalemia vastaan, ja tekemään heille kapinaa."],[4,9,"Mutta me rukoilimme meidän Jumalaamme ja panimme vartiat öin ja päivin heitä vastaan, heidän tähtensä.","Mutta me rukoilimme meidän Jumalaamme ja panimme vartiat öin ja päivin heitä vastaan, heidän tähtensä."],[4,10,"Ja Juuda sanoi: kantajain voima on heikoksi tullut ja multaa on niin paljo, ettemme saa rakentaa muuria.","Ja Juuda sanoi: kantajain voima on heikoksi tullut ja multaa on niin paljo, ettemme saa rakentaa muuria."],[4,11,"Ja meidän vihollisemme sanoivat: ei heidän pidä tietämän eli näkemän, ennenkuin me olemme juuri heidän keskellänsä, tapamme heidät ja estämme työn.","Ja meidän vihollisemme sanoivat: ei heidän pidä tietämän eli näkemän, ennenkuin me olemme juuri heidän keskellänsä, tapamme heidät ja estämme työn."],[4,12,"Ja kuin ne Juudalaiset, jotka heidän tykönänsä asuivat, tulivat ja sanoivat meille kymmenen kertaa: joka paikasta te vielä meidän tykömme palajatte;","Ja kuin ne Juudalaiset, jotka heidän tykönänsä asuivat, tulivat ja sanoivat meille kymmenen kertaa: joka paikasta te vielä meidän tykömme palajatte;"],[4,13,"Niin minä lähetin kansan alas muurin taa tuiviin paikkoihin, heidän sukukuntainsa jälkeen, miekkoinensa, keihäinensä ja joutsinensa.","Niin minä lähetin kansan alas muurin taa tuiviin paikkoihin, heidän sukukuntainsa jälkeen, miekkoinensa, keihäinensä ja joutsinensa."],[4,14,"Ja minä katselin ja valmistin itseni, ja sanoin ylimmäisille ja päämiehille, ja muulle kansalle: älkäät peljätkö heitä, muistakaat suurta ja peljättävää Herraa, ja sotikaat teidän veljeinne, poikainne, tytärtenne, emäntäinne ja kotonne edestä.","Ja minä katselin ja valmistin itseni, ja sanoin ylimmäisille ja päämiehille, ja muulle kansalle: älkäät peljätkö heitä, muistakaat suurta ja peljättävää Herraa, ja sotikaat teidän veljeinne, poikainne, tytärtenne, emäntäinne ja kotonne edestä."],[4,15,"Mutta kuin meidän vihollisemme sen kuulivat, että me olimme tietää saaneet, niin Jumala teki heidän neuvonsa tyhjäksi: ja me palasimme kaikki muurin tykö, jokainen työhönsä.","Mutta kuin meidän vihollisemme sen kuulivat, että me olimme tietää saaneet, niin Jumala teki heidän neuvonsa tyhjäksi: ja me palasimme kaikki muurin tykö, jokainen työhönsä."],[4,16,"Ja tapahtui siitä päivästä, että toinen puoli nuoria miehiäni teki työtä, ja toinen puoli piti keihäitä, kilpiä, joutsia ja rautapaitoja. Ja päämiehet seisoivat koko Juudan huoneen takana.","Ja tapahtui siitä päivästä, että toinen puoli nuoria miehiäni teki työtä, ja toinen puoli piti keihäitä, kilpiä, joutsia ja rautapaitoja. Ja päämiehet seisoivat koko Juudan huoneen takana."],[4,17,"Ne, jotka rakensivat muuria ja kantoivat kuormia, ja jotka sälyttivät, yhdellä kädellä he tekivät työtä ja toisessa pitivät aseen.","Ne, jotka rakensivat muuria ja kantoivat kuormia, ja jotka sälyttivät, yhdellä kädellä he tekivät työtä ja toisessa pitivät aseen."],[4,18,"Ja jokaisella joka siellä rakensi, oli miekka sidottu vyölle, ja niin he rakensivat. Ja se joka soitti vaskitorvea, oli minun tykönäni.","Ja jokaisella joka siellä rakensi, oli miekka sidottu vyölle, ja niin he rakensivat. Ja se joka soitti vaskitorvea, oli minun tykönäni."],[4,19,"Ja minä sanoin ylimmäisille ja päämiehille ja muulle kansalle: työ on suuri ja avara, ja me olemme hajalla muurin päällä, kaukana toinen toisestamme;","Ja minä sanoin ylimmäisille ja päämiehille ja muulle kansalle: työ on suuri ja avara, ja me olemme hajalla muurin päällä, kaukana toinen toisestamme;"],[4,20,"Millä paikalla te kuulette vaskitorven äänen, tulkaat sinne kokoon meidän tykömme: meidän Jumalamme sotii meidän edestämme.","Millä paikalla te kuulette vaskitorven äänen, tulkaat sinne kokoon meidän tykömme: meidän Jumalamme sotii meidän edestämme."],[4,21,"Niin tehkäämme siis työtä; ja toinen puoli heistä piti keihäitä päivän koittamasta niin siihen saakka, että tähdet näkyivät.","Niin tehkäämme siis työtä; ja toinen puoli heistä piti keihäitä päivän koittamasta niin siihen saakka, että tähdet näkyivät."],[4,22,"Ja minä myös sanoin siihen aikaan kansalle: jokainen olkaan yötä palveliainsa kanssa keskellä Jerusalemia, niin että me yöllä ottaisimme vaarin vartiosta ja päivällä työstä.","Ja minä myös sanoin siihen aikaan kansalle: jokainen olkaan yötä palveliainsa kanssa keskellä Jerusalemia, niin että me yöllä ottaisimme vaarin vartiosta ja päivällä työstä."],[4,23,"Mutta minä ja minun veljeni, ja minun palveliani ja vartiat, jotka minua seurasivat, emme riisuneet vaatteitamme; ja jokaisella oli hänen aseensa ja vesi.","Mutta minä ja minun veljeni, ja minun palveliani ja vartiat, jotka minua seurasivat, emme riisuneet vaatteitamme; ja jokaisella oli hänen aseensa ja vesi."],[5,1,"Ja tapahtui sangen suuri kansan ja heidän vaimonsa huuto Juudalaisia heidän veljiänsä vastaan.","Ja tapahtui sangen suuri kansan ja heidän vaimonsa huuto Juudalaisia heidän veljiänsä vastaan."],[5,2,"Ja oli muutamia, jotka sanoivat: meillä on poikia ja tyttäriä, ottakaamme siis (niiden hinnalla) jyviä syödäksemme, että me eläisimme.","Ja oli muutamia, jotka sanoivat: meillä on poikia ja tyttäriä, ottakaamme siis (niiden hinnalla) jyviä syödäksemme, että me eläisimme."],[5,3,"Mutta monikahdat sanoivat: pankaamme meidän peltomme, viinamäkemme ja huoneemme pantiksi, ja ottakaamme jyviä tällä kalliilla ajalla.","Mutta monikahdat sanoivat: pankaamme meidän peltomme, viinamäkemme ja huoneemme pantiksi, ja ottakaamme jyviä tällä kalliilla ajalla."],[5,4,"Ja monikahdat sanoivat: me otimme rahaa lainaksi kuninkaan veroksi, meidän peltoimme ja viinamäkeimme päälle;","Ja monikahdat sanoivat: me otimme rahaa lainaksi kuninkaan veroksi, meidän peltoimme ja viinamäkeimme päälle;"],[5,5,"Sillä meidän ruumiimme on niinkuin veljeimmekin ruumis ja meidän lapsemme niinkuin heidänkin lapsensa; mutta katso, me heitämme poikamme ja tyttäremme orjuuteen, ja jo parhaallansa ovat muutamat meidän tyttäristämme sorretut, ja ei ole voimaa meidän käsissämme; meidän peltomme ja viinamäkemme ovat joutuneet muille.","Sillä meidän ruumiimme on niinkuin veljeimmekin ruumis ja meidän lapsemme niinkuin heidänkin lapsensa; mutta katso, me heitämme poikamme ja tyttäremme orjuuteen, ja jo parhaallansa ovat muutamat meidän tyttäristämme sorretut, ja ei ole voimaa meidän käsissämme; meidän peltomme ja viinamäkemme ovat joutuneet muille."],[5,6,"Kuin minä tämän puheen ja heidän huutonsa kuulin, vihastuin minä sangen kovin.","Kuin minä tämän puheen ja heidän huutonsa kuulin, vihastuin minä sangen kovin."],[5,7,"Ja minä ajattelin sydämessäni, ja nuhtelin ylimmäisiä ja päämiehiä ja sanoin heille: tahdotteko te kukin veljeltänne korkoa ottaa? Ja minä vein suuren joukon heitä vastaan,","Ja minä ajattelin sydämessäni, ja nuhtelin ylimmäisiä ja päämiehiä ja sanoin heille: tahdotteko te kukin veljeltänne korkoa ottaa? Ja minä vein suuren joukon heitä vastaan,"],[5,8,"Ja sanoin heille: me olemme ostaneet veljemme Juudalaiset jälleen, jotka olivat myydyt pakanoille, varamme jälkeen; ja te vielä nyt tahdotte myydä veljenne, jotka meille myydyt ovat; niin he vaikenivat ja ei taitaneet vastata.","Ja sanoin heille: me olemme ostaneet veljemme Juudalaiset jälleen, jotka olivat myydyt pakanoille, varamme jälkeen; ja te vielä nyt tahdotte myydä veljenne, jotka meille myydyt ovat; niin he vaikenivat ja ei taitaneet vastata."],[5,9,"Niin minä sanoin: ei se ole hyvä, minkä te teette; eikö teidän pitäisi vaeltaman meidän Jumalamme pelvossa, pakanain meidän vihollistemme häväistyksen tähden?","Niin minä sanoin: ei se ole hyvä, minkä te teette; eikö teidän pitäisi vaeltaman meidän Jumalamme pelvossa, pakanain meidän vihollistemme häväistyksen tähden?"],[5,10,"Minä myös ja minun veljeni ja palveliani olemme lainanneet heille rahaa ja jyviä; mutta jättäkäämme pois tämä korko.","Minä myös ja minun veljeni ja palveliani olemme lainanneet heille rahaa ja jyviä; mutta jättäkäämme pois tämä korko."],[5,11,"Antakaat heille tänäpänä heidän peltonsa, viinamäkensä, öljypuunsa, huoneensa ja sadas osa rahasta, jyvistä, viinasta ja öljystä, jonka te olette heiltä koroksi vaatineet.","Antakaat heille tänäpänä heidän peltonsa, viinamäkensä, öljypuunsa, huoneensa ja sadas osa rahasta, jyvistä, viinasta ja öljystä, jonka te olette heiltä koroksi vaatineet."],[5,12,"Niin he sanoivat: me annamme jälleen, ja emme ano heiltä mitään; me teemme niinkuin sinä olet sanonut. Ja minä kutsuin papit ja vannotin heitä, että heidän piti niin tekemän.","Niin he sanoivat: me annamme jälleen, ja emme ano heiltä mitään; me teemme niinkuin sinä olet sanonut. Ja minä kutsuin papit ja vannotin heitä, että heidän piti niin tekemän."],[5,13,"Minä pudistin myös helmani ja sanoin: noin Jumala pudistakoon jokaisen miehen huoneestansa ja työstänsä, joka ei tätä sanaa pidä, ja tulkoon niin pudistetuksi ja tyhjäksi. Ja kansa sanoi: amen! Ja he kiittivät Herraa; ja kansa teki niin.","Minä pudistin myös helmani ja sanoin: noin Jumala pudistakoon jokaisen miehen huoneestansa ja työstänsä, joka ei tätä sanaa pidä, ja tulkoon niin pudistetuksi ja tyhjäksi. Ja kansa sanoi: amen! Ja he kiittivät Herraa; ja kansa teki niin."],[5,14,"Ja siitä ajasta, kuin minua käskettiin olla heidän päämiehensä Juudan maassa, joka oli siitä kahdestakymmenennestä vuodesta niin toiseenneljättäkymmentä kuningas Artahsastan vuoteen, kahdestatoistakymmenessä ajastajassa, minä ja minun veljeni emme syöneet päämiehen ruokaa.","Ja siitä ajasta, kuin minua käskettiin olla heidän päämiehensä Juudan maassa, joka oli siitä kahdestakymmenennestä vuodesta niin toiseenneljättäkymmentä kuningas Artahsastan vuoteen, kahdestatoistakymmenessä ajastajassa, minä ja minun veljeni emme syöneet päämiehen ruokaa."],[5,15,"Sillä ne päämiehet, jotka ennen minua olivat, ne olivat raskauttaneet kansaa ja ottaneet leipää ja viinaa heiltä, ja vielä sitte neljäkymmentä sikliä hopiaa, ja olivat antaneet palveliainsa tehdä väkivaltaa kansalle; mutta en minä niin tehnyt Jumalan pelvon tähden.","Sillä ne päämiehet, jotka ennen minua olivat, ne olivat raskauttaneet kansaa ja ottaneet leipää ja viinaa heiltä, ja vielä sitte neljäkymmentä sikliä hopiaa, ja olivat antaneet palveliainsa tehdä väkivaltaa kansalle; mutta en minä niin tehnyt Jumalan pelvon tähden."],[5,16,"Ja minä tein myös työtä muurissa, ja en ostanut yhtään peltoa; ja kaikkein minun palveliaini täytyi tulla sinne kokoon työhön.","Ja minä tein myös työtä muurissa, ja en ostanut yhtään peltoa; ja kaikkein minun palveliaini täytyi tulla sinne kokoon työhön."],[5,17,"Vielä päälliseksi oli myös Juudalaisia ja ylimmäisiä sata ja viisikymmentä minun pöytäni tykönä, jotka olivat tulleet minun tyköni pakanoista, jotka ovat tässä meidän ympärillämme.","Vielä päälliseksi oli myös Juudalaisia ja ylimmäisiä sata ja viisikymmentä minun pöytäni tykönä, jotka olivat tulleet minun tyköni pakanoista, jotka ovat tässä meidän ympärillämme."],[5,18,"Ja minulle valmistettiin joka päivä yksi härkä, ja kuusi valittua lammasta, ja lintuja, ja erilaisia viinoja yltäkyllä joka kymmenes päivä; ja en minä kuitenkaan anonut päämiehen ruokaa, sillä raskas orjuus oli tällä kansalla.","Ja minulle valmistettiin joka päivä yksi härkä, ja kuusi valittua lammasta, ja lintuja, ja erilaisia viinoja yltäkyllä joka kymmenes päivä; ja en minä kuitenkaan anonut päämiehen ruokaa, sillä raskas orjuus oli tällä kansalla."],[5,19,"Minun Jumalani, muista minulle hyväksi kaikki, minkä minä olen tehnyt tälle kansalle.","Minun Jumalani, muista minulle hyväksi kaikki, minkä minä olen tehnyt tälle kansalle."],[6,1,"Kuin Sanballat, Tobia ja Gesem Arabialainen, ja muut meidän vihollisemme kuulivat minun muurit rakentaneeksi, ja ettei yhtään rakoa siihen jäänyt, (vaikka en minä vielä ollut pannut portteja siallensa);","Kuin Sanballat, Tobia ja Gesem Arabialainen, ja muut meidän vihollisemme kuulivat minun muurit rakentaneeksi, ja ettei yhtään rakoa siihen jäänyt, (vaikka en minä vielä ollut pannut portteja siallensa);"],[6,2,"Niin Sanballat ja Gesem lähettivät minun tyköni nämät sanat: tule, ja kokoontukaamme maakyliin Onon laaksoon; mutta he ajattelivat minulle tehdä pahaa.","Niin Sanballat ja Gesem lähettivät minun tyköni nämät sanat: tule, ja kokoontukaamme maakyliin Onon laaksoon; mutta he ajattelivat minulle tehdä pahaa."],[6,3,"Mutta minä lähetin heille sanansaattajat, sanoen: minulla on sangen suuri työ tehtävänä, en minä saa tulla alas. Miksi pitäis työ lakkaaman, minun jättäissäni sitä ja tullessani alas teidän tykönne?","Mutta minä lähetin heille sanansaattajat, sanoen: minulla on sangen suuri työ tehtävänä, en minä saa tulla alas. Miksi pitäis työ lakkaaman, minun jättäissäni sitä ja tullessani alas teidän tykönne?"],[6,4,"Ja he lähettivät minun tyköni täyttä neljä kertaa sillä tavalla; ja minä vastasin heitä jälleen sillä tavalla.","Ja he lähettivät minun tyköni täyttä neljä kertaa sillä tavalla; ja minä vastasin heitä jälleen sillä tavalla."],[6,5,"Niin Sanballat lähetti viidennen kerran palveliansa minun tyköni avoimen kirjan kanssa kädessänsä,","Niin Sanballat lähetti viidennen kerran palveliansa minun tyköni avoimen kirjan kanssa kädessänsä,"],[6,6,"Jossa näin oli kirjoitettu: se on pakanain eteen tullut, ja Gasmu on sanonut, että sinä ja Juudalaiset ajattelette luopua pois: ja sentähden sinä rakennat muureja; ja sinä tahdot olla heidän kuninkaansa tässä asiassa.","Jossa näin oli kirjoitettu: se on pakanain eteen tullut, ja Gasmu on sanonut, että sinä ja Juudalaiset ajattelette luopua pois: ja sentähden sinä rakennat muureja; ja sinä tahdot olla heidän kuninkaansa tässä asiassa."],[6,7,"Ja sinä olet toimittanut prophetat jotka sinua pitää kuuluttaman Jerusalemissa ja sanoman: hän on Juudalaisten kuningas. Ja nyt pitää se asia tuleman kuninkaan eteen; sentähden tule nyt ja pitäkäämme neuvoa toinen toisemme kanssa siitä asiasta.","Ja sinä olet toimittanut prophetat jotka sinua pitää kuuluttaman Jerusalemissa ja sanoman: hän on Juudalaisten kuningas. Ja nyt pitää se asia tuleman kuninkaan eteen; sentähden tule nyt ja pitäkäämme neuvoa toinen toisemme kanssa siitä asiasta."],[6,8,"Mutta minä lähetin hänen tykönsä ja annoin hänelle sanoa: ei se ole niin tapahtunut kuin sinä sanot; vaan sinä olet sen ajatellut omasta sydämestäs.","Mutta minä lähetin hänen tykönsä ja annoin hänelle sanoa: ei se ole niin tapahtunut kuin sinä sanot; vaan sinä olet sen ajatellut omasta sydämestäs."],[6,9,"Sillä he kaikki tahtoivat meitä peljättää, ja ajattelivat: heidän kätensä pitää väsymän työstä, ettei he enää työtä tekisi. Nyt siis vahvista minun käteni!","Sillä he kaikki tahtoivat meitä peljättää, ja ajattelivat: heidän kätensä pitää väsymän työstä, ettei he enää työtä tekisi. Nyt siis vahvista minun käteni!"],[6,10,"Ja minä tulin Semajan huoneesen, Delajan pojan, Mehetabelin pojan, joka oli sulkenut itsensä sisälle. Ja hän sanoi: käykäämme kokoon Jumalan huoneesen keskelle templiä ja sulkekaamme templin ovet; sillä he tulevat tappamaan sinua, ja he tulevat yöllä sinua tappamaan.","Ja minä tulin Semajan huoneesen, Delajan pojan, Mehetabelin pojan, joka oli sulkenut itsensä sisälle. Ja hän sanoi: käykäämme kokoon Jumalan huoneesen keskelle templiä ja sulkekaamme templin ovet; sillä he tulevat tappamaan sinua, ja he tulevat yöllä sinua tappamaan."],[6,11,"Minä vastasin; pitääkö senkaltaisen miehen kuin minä olen pakeneman? ja kuka olis niinkuin minä, joka menis templiin, että hän sais elää? En minä mene sinne.","Minä vastasin; pitääkö senkaltaisen miehen kuin minä olen pakeneman? ja kuka olis niinkuin minä, joka menis templiin, että hän sais elää? En minä mene sinne."],[6,12,"Sillä katso, minä ymmärsin hyvin, ettei Jumala ollut häntä lähettänyt; vaan hän ennusti minua vastaan, sillä Tobia ja Sanballat olivat palkanneet hänen.","Sillä katso, minä ymmärsin hyvin, ettei Jumala ollut häntä lähettänyt; vaan hän ennusti minua vastaan, sillä Tobia ja Sanballat olivat palkanneet hänen."],[6,13,"Sentähden hän oli palkattu, että minä olisin peljännyt ja olisin niin tehnyt, ja syntiä tehnyt, että he olisivat saaneet pahan huudon, jolla he olisivat minua häväisseet.","Sentähden hän oli palkattu, että minä olisin peljännyt ja olisin niin tehnyt, ja syntiä tehnyt, että he olisivat saaneet pahan huudon, jolla he olisivat minua häväisseet."],[6,14,"Minun Jumalani! muista Tobiaa ja Sanballatia näiden heidän töidensä jälkeen, ja Noadiaa naisprophetaa ja muita prophetaita jotka minua tahtoivat peljättää.","Minun Jumalani! muista Tobiaa ja Sanballatia näiden heidän töidensä jälkeen, ja Noadiaa naisprophetaa ja muita prophetaita jotka minua tahtoivat peljättää."],[6,15,"Ja muuri tuli valmiiksi viidennellä päivällä kolmattakymmentä Elulin kuuta, kahden päivän kuudettakymmentä kuluttua.","Ja muuri tuli valmiiksi viidennellä päivällä kolmattakymmentä Elulin kuuta, kahden päivän kuudettakymmentä kuluttua."],[6,16,"Niin tapahtui, että kuin kaikki meidän vihollisemme sen kuulivat, niin kaikki pakanat pelkäsivät, jotka meidän ympärillämme olivat, ja he hämmästyivät kovin keskenänsä; sillä he ymmärsivät tämän työn olevan meidän Jumalaltamme.","Niin tapahtui, että kuin kaikki meidän vihollisemme sen kuulivat, niin kaikki pakanat pelkäsivät, jotka meidän ympärillämme olivat, ja he hämmästyivät kovin keskenänsä; sillä he ymmärsivät tämän työn olevan meidän Jumalaltamme."],[6,17,"Ja siihen aikaan oli monta Juudan ylimmäisistä siellä, joiden kirjat menivät usein Tobialle ja Tobian kirjat heidän tykönsä.","Ja siihen aikaan oli monta Juudan ylimmäisistä siellä, joiden kirjat menivät usein Tobialle ja Tobian kirjat heidän tykönsä."],[6,18,"Sillä monta oli Juudalaisista, jotka olivat vannoneet hänen kanssansa; sillä hän oli Sekanian Aran pojan vävy, ja hänen pojallansa Johananilla oli Mesullamin Berekian pojan tytär.","Sillä monta oli Juudalaisista, jotka olivat vannoneet hänen kanssansa; sillä hän oli Sekanian Aran pojan vävy, ja hänen pojallansa Johananilla oli Mesullamin Berekian pojan tytär."],[6,19,"Ja he puhuivat hyvin minun edessäni hänestä ja veivät minun puheeni hänen tykönsä; niin Tobia lähetti kirjan minulle peljättääksensä minua.","Ja he puhuivat hyvin minun edessäni hänestä ja veivät minun puheeni hänen tykönsä; niin Tobia lähetti kirjan minulle peljättääksensä minua."],[7,1,"Mutta sittekuin muurit olivat rakennetut, panin minä portit; ja toimitettiin ovenvartiat, veisaajat ja Leviläiset.","Mutta sittekuin muurit olivat rakennetut, panin minä portit; ja toimitettiin ovenvartiat, veisaajat ja Leviläiset."],[7,2,"Ja minä käskin veljeäni Hanania, ja Hananiaa, linnan vanhinta Jerusalemissa (sillä hän oli uskollinen ja Jumalaa pelkääväinen mies monen suhteen),","Ja minä käskin veljeäni Hanania, ja Hananiaa, linnan vanhinta Jerusalemissa (sillä hän oli uskollinen ja Jumalaa pelkääväinen mies monen suhteen),"],[7,3,"Ja sanoin heille: ei Jerusalemin portteja ennen pidä avattaman, kuin aurinko lämpiää, ja kuin vielä työtä tehdään, niin pitää portit pantaman kiinni ja teljettämän. Ja vartiat asetettiin Jerusalemin asuvaisista jokainen paikkaansa, ja kukin oman huoneensa kohdalle;","Ja sanoin heille: ei Jerusalemin portteja ennen pidä avattaman, kuin aurinko lämpiää, ja kuin vielä työtä tehdään, niin pitää portit pantaman kiinni ja teljettämän. Ja vartiat asetettiin Jerusalemin asuvaisista jokainen paikkaansa, ja kukin oman huoneensa kohdalle;"],[7,4,"Sillä kaupunki oli avara ja suuri, mutta kansaa oli siinä vähän; ja ei olleet huoneet rakennetut.","Sillä kaupunki oli avara ja suuri, mutta kansaa oli siinä vähän; ja ei olleet huoneet rakennetut."],[7,5,"Ja minun Jumalani lykkäsi mieleeni, että minä kokosin ylimmäiset ja päämiehet ja kansan, ja luin heidät; ja minä löysin heidän mieslukunsa kirjan, jotka ennen olivat tulleet vankeudesta, ja minä löysin siinä kirjoitettuna.","Ja minun Jumalani lykkäsi mieleeni, että minä kokosin ylimmäiset ja päämiehet ja kansan, ja luin heidät; ja minä löysin heidän mieslukunsa kirjan, jotka ennen olivat tulleet vankeudesta, ja minä löysin siinä kirjoitettuna."],[7,6,"Nämät ovat maakunnan lapset, jotka palasivat poisviedyistä vangeista, jotka Nebukadnetsar Babelin kuningas oli vienyt pois; ja he palasivat Jerusalemiin ja Juudaan, jokainen kaupunkiinsa,","Nämät ovat maakunnan lapset, jotka palasivat poisviedyistä vangeista, jotka Nebukadnetsar Babelin kuningas oli vienyt pois; ja he palasivat Jerusalemiin ja Juudaan, jokainen kaupunkiinsa,"],[7,7,"Jotka tulivat Serubbabelin, Jesuan, Nehemia, Asarian, Raamian, Nahamanin, Mordekain, Bilsan, Misperetin, Bigvain, Nehumin ja Baenan kanssa. Tämä on Israelin miesten luku:","Jotka tulivat Serubbabelin, Jesuan, Nehemia, Asarian, Raamian, Nahamanin, Mordekain, Bilsan, Misperetin, Bigvain, Nehumin ja Baenan kanssa. Tämä on Israelin miesten luku:"],[7,8,"Baroksen lapsia, kaksituhatta, sata ja kaksikahdeksattakymmentä;","Baroksen lapsia, kaksituhatta, sata ja kaksikahdeksattakymmentä;"],[7,9,"Sephatian lapsia, kolmesataa ja kaksikahdeksattakymmentä;","Sephatian lapsia, kolmesataa ja kaksikahdeksattakymmentä;"],[7,10,"Aran lapsia, kuusisataa ja kaksikuudettakymmentä;","Aran lapsia, kuusisataa ja kaksikuudettakymmentä;"],[7,11,"Pahatmoabin lapsia, Jesuan ja Joabin lasten seassa, kaksituhatta, kahdeksansataa ja kahdeksantoistakymmentä;","Pahatmoabin lapsia, Jesuan ja Joabin lasten seassa, kaksituhatta, kahdeksansataa ja kahdeksantoistakymmentä;"],[7,12,"Elamin lapsia, tuhannen, kaksisataa ja neljäkuudettakymmentä;","Elamin lapsia, tuhannen, kaksisataa ja neljäkuudettakymmentä;"],[7,13,"Sattun lapsia, kahdeksansataa ja viisiviidettäkymmentä;","Sattun lapsia, kahdeksansataa ja viisiviidettäkymmentä;"],[7,14,"Sakkain lapsia seitsemänsataa ja kuusikymmentä;","Sakkain lapsia seitsemänsataa ja kuusikymmentä;"],[7,15,"Binnuin lapsia, kuusisataa ja kahdeksanviidettäkymmentä;","Binnuin lapsia, kuusisataa ja kahdeksanviidettäkymmentä;"],[7,16,"Bebain lapsia, kuusisataa ja kahdeksankolmattakymmentä;","Bebain lapsia, kuusisataa ja kahdeksankolmattakymmentä;"],[7,17,"Asgadin lapsia, kaksituhatta, kolmesataa ja kaksikolmattakymmentä;","Asgadin lapsia, kaksituhatta, kolmesataa ja kaksikolmattakymmentä;"],[7,18,"Adonikamin lapsia, kuusisataa ja seitsemänseitsemättäkymmentä;","Adonikamin lapsia, kuusisataa ja seitsemänseitsemättäkymmentä;"],[7,19,"Bigvain lapsia, kaksituhatta ja seitsemänseitsemättäkymmentä;","Bigvain lapsia, kaksituhatta ja seitsemänseitsemättäkymmentä;"],[7,20,"Adinin lapsia, kuusisataa ja viisikuudettakymmentä;","Adinin lapsia, kuusisataa ja viisikuudettakymmentä;"],[7,21,"Aterin lapsia Hiskiasta, yhdeksänkymmentä ja kahdeksan;","Aterin lapsia Hiskiasta, yhdeksänkymmentä ja kahdeksan;"],[7,22,"Hasumin lapsia, kolmesataa ja kahdeksankolmattakymmentä;","Hasumin lapsia, kolmesataa ja kahdeksankolmattakymmentä;"],[7,23,"Besain lapsia, kolmesataa ja neljäkolmattakymmentä;","Besain lapsia, kolmesataa ja neljäkolmattakymmentä;"],[7,24,"Hariphin lapsia, sata ja kaksitoistakymmentä;","Hariphin lapsia, sata ja kaksitoistakymmentä;"],[7,25,"Gibeonin lapsia, yhdeksänkymmentä ja viisi;","Gibeonin lapsia, yhdeksänkymmentä ja viisi;"],[7,26,"Betlehemin ja Netophan miehiä sata ja kahdeksanyhdeksättäkymmentä;","Betlehemin ja Netophan miehiä sata ja kahdeksanyhdeksättäkymmentä;"],[7,27,"Anatotin miehiä, sata ja kahdeksankolmattakymmentä;","Anatotin miehiä, sata ja kahdeksankolmattakymmentä;"],[7,28,"Betasmavetin miehiä, kaksiviidettäkymmentä;","Betasmavetin miehiä, kaksiviidettäkymmentä;"],[7,29,"Kirjatjearimin, Kaphiran ja Beerotin miehiä, seitsemänsataa ja kolmeviidettäkymmentä;","Kirjatjearimin, Kaphiran ja Beerotin miehiä, seitsemänsataa ja kolmeviidettäkymmentä;"],[7,30,"Raman ja Gabaan miehiä, kuusisataa ja yksikolmattakymmentä;","Raman ja Gabaan miehiä, kuusisataa ja yksikolmattakymmentä;"],[7,31,"Mikmaan miehiä, sata ja kaksikolmattakymmentä;","Mikmaan miehiä, sata ja kaksikolmattakymmentä;"],[7,32,"Betelin ja Ain miehiä, sata ja kolmekolmattakymmentä;","Betelin ja Ain miehiä, sata ja kolmekolmattakymmentä;"],[7,33,"Toisen Nebon miehiä, kaksikuudettakymmentä;","Toisen Nebon miehiä, kaksikuudettakymmentä;"],[7,34,"Toisen Elamin lapsia, tuhannen, kaksisataa ja neljäkuudettakymmentä;","Toisen Elamin lapsia, tuhannen, kaksisataa ja neljäkuudettakymmentä;"],[7,35,"Harimin lapsia, kolmesataa ja kaksikymmentä;","Harimin lapsia, kolmesataa ja kaksikymmentä;"],[7,36,"Jerihon lapsia, kolmesataa ja viisiviidettäkymmentä;","Jerihon lapsia, kolmesataa ja viisiviidettäkymmentä;"],[7,37,"Lodin, Hadadin ja Onon lapsia, seitsemänsataa ja yksikolmattakymmentä;","Lodin, Hadadin ja Onon lapsia, seitsemänsataa ja yksikolmattakymmentä;"],[7,38,"Senaan lapsia, kolmetuhatta, yhdeksänsataa ja kolmekymmentä;","Senaan lapsia, kolmetuhatta, yhdeksänsataa ja kolmekymmentä;"],[7,39,"Papit: Jedajan lapsia Jesuan huoneesta, yhdeksänsataa ja kolmekahdeksattakymmentä;","Papit: Jedajan lapsia Jesuan huoneesta, yhdeksänsataa ja kolmekahdeksattakymmentä;"],[7,40,"Immerin lapsia, tuhannen ja kaksikuudettakymmentä;","Immerin lapsia, tuhannen ja kaksikuudettakymmentä;"],[7,41,"Pashurin lapsia, tuhannen, kaksisataa ja seitsemänviidettäkymmentä;","Pashurin lapsia, tuhannen, kaksisataa ja seitsemänviidettäkymmentä;"],[7,42,"Harimin lapsia, tuhannen ja seitsemäntoistakymmentä;","Harimin lapsia, tuhannen ja seitsemäntoistakymmentä;"],[7,43,"Leviläiset: Jesuan lapsia Kadmielista Hodevan lasten seasta, neljäkahdeksattakymmentä;","Leviläiset: Jesuan lapsia Kadmielista Hodevan lasten seasta, neljäkahdeksattakymmentä;"],[7,44,"Veisaajat: Asaphin lapsia, sata ja kahdeksanviidettäkymmentä;","Veisaajat: Asaphin lapsia, sata ja kahdeksanviidettäkymmentä;"],[7,45,"Ovenvartiat olivat Sallumin lapset, Aterin lapset, Talmonin lapset, Akkubin lapset, Hatitan lapset, Sobain lapset, (kaikki yhteen) sata ja kahdeksanneljättäkymmentä;","Ovenvartiat olivat Sallumin lapset, Aterin lapset, Talmonin lapset, Akkubin lapset, Hatitan lapset, Sobain lapset, (kaikki yhteen) sata ja kahdeksanneljättäkymmentä;"],[7,46,"Netinimit: Zihan lapset, Hasuphan lapset, Taboatin lapset,","Netinimit: Zihan lapset, Hasuphan lapset, Taboatin lapset,"],[7,47,"Keroksen lapset, Sian lapset, Padonin lapset,","Keroksen lapset, Sian lapset, Padonin lapset,"],[7,48,"Libanan lapset, Hagaban lapset, Salmain lapset,","Libanan lapset, Hagaban lapset, Salmain lapset,"],[7,49,"Hananin lapset, Giddelin lapset, Gaharin lapset,","Hananin lapset, Giddelin lapset, Gaharin lapset,"],[7,50,"Reajan lapset, Resinin lapset, Nekodan lapset,","Reajan lapset, Resinin lapset, Nekodan lapset,"],[7,51,"Gassamin lapset, Ussan lapset, Passean lapset,","Gassamin lapset, Ussan lapset, Passean lapset,"],[7,52,"Besain lapset, Megunimin lapset, Nephusesimin lapset,","Besain lapset, Megunimin lapset, Nephusesimin lapset,"],[7,53,"Bakbukin lapset, Haguphan lapset, Harhurin lapset,","Bakbukin lapset, Haguphan lapset, Harhurin lapset,"],[7,54,"Batslitin lapset, Mehidan lapset, Harsan lapset,","Batslitin lapset, Mehidan lapset, Harsan lapset,"],[7,55,"Barkoksen lapset, Siseran lapset, Thaman lapset,","Barkoksen lapset, Siseran lapset, Thaman lapset,"],[7,56,"Netsian lapset, Hatiphan lapset.","Netsian lapset, Hatiphan lapset."],[7,57,"Salomon palveliain lapsia oli: Sotain lapset, Sopheretin lapset, Peridan lapset,","Salomon palveliain lapsia oli: Sotain lapset, Sopheretin lapset, Peridan lapset,"],[7,58,"Jaelan lapset, Darkonin lapset, Giddelin lapset,","Jaelan lapset, Darkonin lapset, Giddelin lapset,"],[7,59,"Sephatian lapset, Hattilin lapset, PokeretZebaimin lapset, Amonin lapset.","Sephatian lapset, Hattilin lapset, PokeretZebaimin lapset, Amonin lapset."],[7,60,"Kaikkia Netinimein ja Salomon palveliain lapsia oli (yhteen) kolmesataa, yhdeksänkymmentä ja kaksi.","Kaikkia Netinimein ja Salomon palveliain lapsia oli (yhteen) kolmesataa, yhdeksänkymmentä ja kaksi."],[7,61,"Ja nämä menivät ylös Telmelasta, Telharsasta: Kerubi, Addon ja Immer; mutta ei he tietäneet isäinsä huonetta taikka siementänsä, olivatko he Israelista:","Ja nämä menivät ylös Telmelasta, Telharsasta: Kerubi, Addon ja Immer; mutta ei he tietäneet isäinsä huonetta taikka siementänsä, olivatko he Israelista:"],[7,62,"Delajan lapset, Tobian lapset, Nekodan lapset, kuusisataa ja kaksiviidettäkymmentä;","Delajan lapset, Tobian lapset, Nekodan lapset, kuusisataa ja kaksiviidettäkymmentä;"],[7,63,"Ja papeista: Hobajan lapset, Hakkotsin lapset, Barsillain lapset, joka otti emännän Barsillain Gileadilaisen tyttäristä, ja kutsuttiin sitte heidän nimellänsä.","Ja papeista: Hobajan lapset, Hakkotsin lapset, Barsillain lapset, joka otti emännän Barsillain Gileadilaisen tyttäristä, ja kutsuttiin sitte heidän nimellänsä."],[7,64,"Nämä etsivät sukukuntansa polvilukukirjaa; ja ettei sitä löydetty, hyljättiin he pappeudesta.","Nämä etsivät sukukuntansa polvilukukirjaa; ja ettei sitä löydetty, hyljättiin he pappeudesta."],[7,65,"Ja Tirsata sanoi heille, ettei heidän pitänyt syömän siitä kaikkein pyhimmästä, ennenkuin pappi seisois valkeudessa ja täydellisyydessä.","Ja Tirsata sanoi heille, ettei heidän pitänyt syömän siitä kaikkein pyhimmästä, ennenkuin pappi seisois valkeudessa ja täydellisyydessä."],[7,66,"Koko joukko yhteen oli kaksiviidettäkymmentä tuhatta, kolmesataa ja kuusikymmentä,","Koko joukko yhteen oli kaksiviidettäkymmentä tuhatta, kolmesataa ja kuusikymmentä,"],[7,67,"Paitsi heidän palvelioitansa ja piikojansa, joita oli seitsemäntuhatta, kolmesataa ja seitsemänneljättäkymmentä. Niin myös heidän seassansa oli veisaajia, miehiä ja vaimoja, kaksisataa ja viisiviidettäkymmentä;","Paitsi heidän palvelioitansa ja piikojansa, joita oli seitsemäntuhatta, kolmesataa ja seitsemänneljättäkymmentä. Niin myös heidän seassansa oli veisaajia, miehiä ja vaimoja, kaksisataa ja viisiviidettäkymmentä;"],[7,68,"Seitsemänsataa ja kuusineljättäkymmentä hevoista; kaksisataa ja viisiviidettäkymmentä muulia;","Seitsemänsataa ja kuusineljättäkymmentä hevoista; kaksisataa ja viisiviidettäkymmentä muulia;"],[7,69,"Neljäsataa ja viisineljättäkymmentä kamelia; kuusituhatta, seitsemänsataa ja kaksikymmentä aasia.","Neljäsataa ja viisineljättäkymmentä kamelia; kuusituhatta, seitsemänsataa ja kaksikymmentä aasia."],[7,70,"Ja muutamat ylimmäistä isistä antoivat rakennukseen: Tirsata antoi tavaraksi tuhannen kultapenninkiä, viisikymmentä maljaa, viisisataa ja kolmekymmentä papin hametta.","Ja muutamat ylimmäistä isistä antoivat rakennukseen: Tirsata antoi tavaraksi tuhannen kultapenninkiä, viisikymmentä maljaa, viisisataa ja kolmekymmentä papin hametta."],[7,71,"Ja muutamat ylimmäisistä isistä antoivat rakennuksen tavaraksi kaksikymmentä tuhatta kultapenninkiä, kaksituhatta ja kaksisataa leiviskää hopiaa.","Ja muutamat ylimmäisistä isistä antoivat rakennuksen tavaraksi kaksikymmentä tuhatta kultapenninkiä, kaksituhatta ja kaksisataa leiviskää hopiaa."],[7,72,"Ja muu kansa antoi kaksikymmentä tuhatta kultapenninkiä, ja kaksituhatta leiviskää hopiaa, ja seitsemänseitsemättäkymmentä papin hametta.","Ja muu kansa antoi kaksikymmentä tuhatta kultapenninkiä, ja kaksituhatta leiviskää hopiaa, ja seitsemänseitsemättäkymmentä papin hametta."],[7,73,"Ja papit, Leviläiset, ovenvartiat, veisaajat, ja muutamat kansasta ja Netinimit ja koko Israel asuivat kaupungeissa. Ja seitsemännen kuukauden lähestyessä olivat Israelin lapset kaupungeissa.","Ja papit, Leviläiset, ovenvartiat, veisaajat, ja muutamat kansasta ja Netinimit ja koko Israel asuivat kaupungeissa. Ja seitsemännen kuukauden lähestyessä olivat Israelin lapset kaupungeissa."],[8,1,"Sitte kokoontui kaikki kansa niinkuin yksi mies sille kadulle, joka on Vesiportin edessä, ja sanoivat Esralle, kirjanoppineelle, että hän tois Moseksen lakikirjan, jonka Herra oli Israelille käskenyt.","Sitte kokoontui kaikki kansa niinkuin yksi mies sille kadulle, joka on Vesiportin edessä, ja sanoivat Esralle, kirjanoppineelle, että hän tois Moseksen lakikirjan, jonka Herra oli Israelille käskenyt."],[8,2,"Ja Esra pappi toi lakikirjan kansan eteen, sekä miesten että vaimoin, ja kaikkein jotka ymmärtää ja kuulla taisivat, ensimäisenä päivänä seitsemättä kuuta.","Ja Esra pappi toi lakikirjan kansan eteen, sekä miesten että vaimoin, ja kaikkein jotka ymmärtää ja kuulla taisivat, ensimäisenä päivänä seitsemättä kuuta."],[8,3,"Ja hän luki siitä kadulla Vesiportin edessä aamusta hamaan puolipäivään asti miesten ja vaimoin edessä, ja jokaisen joka ymmärtää taisi; ja kaiken kansan korvat olivat lakikirjaan käännetyt.","Ja hän luki siitä kadulla Vesiportin edessä aamusta hamaan puolipäivään asti miesten ja vaimoin edessä, ja jokaisen joka ymmärtää taisi; ja kaiken kansan korvat olivat lakikirjaan käännetyt."],[8,4,"Ja Esra, kirjanoppinut, seisoi korkialla puuistuimella, jonka he sitä varten olivat tehneet; ja Mattitia, Sema, Anaja, Uria, Hilkia ja Maeseja seisoivat hänen vieressänsä hänen oikialla puolellansa; ja hänen vasemmalla puolellansa seisoivat Pedaja, Misael, Malkia, Hasum, Hasbaddana, Sakaria ja Mesullam.","Ja Esra, kirjanoppinut, seisoi korkialla puuistuimella, jonka he sitä varten olivat tehneet; ja Mattitia, Sema, Anaja, Uria, Hilkia ja Maeseja seisoivat hänen vieressänsä hänen oikialla puolellansa; ja hänen vasemmalla puolellansa seisoivat Pedaja, Misael, Malkia, Hasum, Hasbaddana, Sakaria ja Mesullam."],[8,5,"Ja Esra avasi kirjan kaiken kansan edessä; sillä hän seisoi ylempänä kaikkea kansaa. Ja kuin hän sen avasi, niin seisoi kaikki kansa.","Ja Esra avasi kirjan kaiken kansan edessä; sillä hän seisoi ylempänä kaikkea kansaa. Ja kuin hän sen avasi, niin seisoi kaikki kansa."],[8,6,"Ja Esra kiitti Herraa, suurta Jumalaa, ja kaikki kansa vastasi nostetuilla käsillä: amen! ja he kumarsivat ja rukoilivat Herraa kasvoillansa maassa.","Ja Esra kiitti Herraa, suurta Jumalaa, ja kaikki kansa vastasi nostetuilla käsillä: amen! ja he kumarsivat ja rukoilivat Herraa kasvoillansa maassa."],[8,7,"Ja Jesua, Bani, Serebia, Jamin, Akub, Sabtai, Hodija, Maeseja, Kelita, Asaria, Josabad, Hanan, Pelaja ja Leviläiset opettivat kansan lakia ymmärtämään; ja kansa seisoi alallansa.","Ja Jesua, Bani, Serebia, Jamin, Akub, Sabtai, Hodija, Maeseja, Kelita, Asaria, Josabad, Hanan, Pelaja ja Leviläiset opettivat kansan lakia ymmärtämään; ja kansa seisoi alallansa."],[8,8,"Ja he lukivat Jumalan lakikirjan selkiästi ja niin ymmärrettävästi, että he ymmärsivät, mitä luettiin.","Ja he lukivat Jumalan lakikirjan selkiästi ja niin ymmärrettävästi, että he ymmärsivät, mitä luettiin."],[8,9,"Ja Nehemia, joka on Tirsata, ja Esra pappi, kirjanoppinut, ja Leviläiset jotka kansan opettivat ymmärtämään, sanoivat kansalle: tämä päivä on pyhä Herralle teidän Jumalallenne: älkäät murehtiko ja älkäät itkekö! sillä kuin kansa kuuli lain sanat, niin he kaikki itkivät.","Ja Nehemia, joka on Tirsata, ja Esra pappi, kirjanoppinut, ja Leviläiset jotka kansan opettivat ymmärtämään, sanoivat kansalle: tämä päivä on pyhä Herralle teidän Jumalallenne: älkäät murehtiko ja älkäät itkekö! sillä kuin kansa kuuli lain sanat, niin he kaikki itkivät."],[8,10,"Ja hän sanoi heille: menkäät ja syökäät lihavaa, ja juokaat makiaa, ja lähettäkäät niille myös osa, joilla ei mitään ole valmistettu; tämä päivä on pyhä meidän Herrallemme, sentähden älkäät murehtiko; sillä Herran ilo on teidän väkevyytenne.","Ja hän sanoi heille: menkäät ja syökäät lihavaa, ja juokaat makiaa, ja lähettäkäät niille myös osa, joilla ei mitään ole valmistettu; tämä päivä on pyhä meidän Herrallemme, sentähden älkäät murehtiko; sillä Herran ilo on teidän väkevyytenne."],[8,11,"Ja Leviläiset vaikittivat kaiken kansan ja sanoivat: olkaat ääneti, sillä tämä päivä on pyhä, älkäät murehtiko!","Ja Leviläiset vaikittivat kaiken kansan ja sanoivat: olkaat ääneti, sillä tämä päivä on pyhä, älkäät murehtiko!"],[8,12,"Ja kaikki kansa meni syömään ja juomaan, ja lähettämään osia ulos, ja tekivät suuren ilon; sillä he olivat ymmärtäneet ne sanat, jotka heille olivat ilmoitetut.","Ja kaikki kansa meni syömään ja juomaan, ja lähettämään osia ulos, ja tekivät suuren ilon; sillä he olivat ymmärtäneet ne sanat, jotka heille olivat ilmoitetut."],[8,13,"Toisena päivänä tulivat ylimmäiset isät kaikesta kansasta, papit ja Leviläiset kokoon, Esran kirjanoppineen tykö, oppimaan lain sanoja.","Toisena päivänä tulivat ylimmäiset isät kaikesta kansasta, papit ja Leviläiset kokoon, Esran kirjanoppineen tykö, oppimaan lain sanoja."],[8,14,"Ja he löysivät laissa kirjoitetun, että Herra oli käskenyt Moseksen kautta Israelin lasten asua lehtimajoissa seitsemännen kuun juhlalla.","Ja he löysivät laissa kirjoitetun, että Herra oli käskenyt Moseksen kautta Israelin lasten asua lehtimajoissa seitsemännen kuun juhlalla."],[8,15,"Ja he antoivat sen julkisesti ilmoittaa ja kuuluttaa kaikissa kaupungeissansa ja Jerusalemissa, ja sanoa: menkäät ulos vuorelle ja tuokaat öljypuun oksia, balsamipuun oksia, myrrhamipuun oksia, palmupuun oksia ja paksuista puista oksia, tehdäksenne majoja, niinkuin kirjoitettu on.","Ja he antoivat sen julkisesti ilmoittaa ja kuuluttaa kaikissa kaupungeissansa ja Jerusalemissa, ja sanoa: menkäät ulos vuorelle ja tuokaat öljypuun oksia, balsamipuun oksia, myrrhamipuun oksia, palmupuun oksia ja paksuista puista oksia, tehdäksenne majoja, niinkuin kirjoitettu on."],[8,16,"Ja kansa menivät ulos ja toivat, ja tekivät itsellensä lehtimajoja, jokainen kattonsa päälle ja kartanoihinsa, ja Jumalan huoneen kartanoihin, ja Vesiportin kadulle, ja Ephraimin portin kadulle.","Ja kansa menivät ulos ja toivat, ja tekivät itsellensä lehtimajoja, jokainen kattonsa päälle ja kartanoihinsa, ja Jumalan huoneen kartanoihin, ja Vesiportin kadulle, ja Ephraimin portin kadulle."],[8,17,"Ja kaikki kansa, joka palannut oli vankeudesta, teki lehtimajoja ja asui niissä; sillä ei Israelin lapset niin olleet tehneet hamasta Josuan Nunin pojan ajasta niin siihen päivään asti. Ja siinä oli sangen suuri ilo.","Ja kaikki kansa, joka palannut oli vankeudesta, teki lehtimajoja ja asui niissä; sillä ei Israelin lapset niin olleet tehneet hamasta Josuan Nunin pojan ajasta niin siihen päivään asti. Ja siinä oli sangen suuri ilo."],[8,18,"Ja luettiin joka päivä Jumalan lakikirjaa, ensimmäisestä päivästä niin viimeiseen. Ja he pitivät juhlaa seitsemän päivää ja kahdeksantena päivänä päätöksen, tavan jälkeen.","Ja luettiin joka päivä Jumalan lakikirjaa, ensimmäisestä päivästä niin viimeiseen. Ja he pitivät juhlaa seitsemän päivää ja kahdeksantena päivänä päätöksen, tavan jälkeen."],[9,1,"Neljäntenä päivänä kolmattakymmentä tätä kuuta tulivat Israelin lapset kokoon, paastoten, säkeissä, ja multaa päällänsä.","Neljäntenä päivänä kolmattakymmentä tätä kuuta tulivat Israelin lapset kokoon, paastoten, säkeissä, ja multaa päällänsä."],[9,2,"Ja he eroittivat Israelin siemenen kaikista muukalaisista lapsista; ja he tulivat edes ja tunnustivat syntinsä ja isäinsä pahat teot.","Ja he eroittivat Israelin siemenen kaikista muukalaisista lapsista; ja he tulivat edes ja tunnustivat syntinsä ja isäinsä pahat teot."],[9,3,"Ja he nousivat ylös siallensa, ja heidän edessänsä luettiin neljä kertaa päivässä Herran heidän Jumalansa lakikirjasta; ja he tunnustivat, ja rukoilivat Herraa Jumalaansa neljä kertaa päivässä.","Ja he nousivat ylös siallensa, ja heidän edessänsä luettiin neljä kertaa päivässä Herran heidän Jumalansa lakikirjasta; ja he tunnustivat, ja rukoilivat Herraa Jumalaansa neljä kertaa päivässä."],[9,4,"Ja Leviläisten korkopaikalle nousivat Jesua, Bani, Kadmiel, Sebania, Bunni, Serebia, Bani ja Kenani, ja huusivat suurella äänellä Herran Jumalansa tykö.","Ja Leviläisten korkopaikalle nousivat Jesua, Bani, Kadmiel, Sebania, Bunni, Serebia, Bani ja Kenani, ja huusivat suurella äänellä Herran Jumalansa tykö."],[9,5,"Ja Leviläiset Jesua, Bani, Kadmiel, Hasabnea, Serebia, Hodia, Sebania ja Petahia sanoivat: nouskaat, kiittäkäät Herraa teidän Jumalaanne ijankaikkisesta ijankaikkiseen! Ja sinun kunnias nimi kiitetään, joka on korotettu ylitse kaiken siunauksen ja kiitoksen.","Ja Leviläiset Jesua, Bani, Kadmiel, Hasabnea, Serebia, Hodia, Sebania ja Petahia sanoivat: nouskaat, kiittäkäät Herraa teidän Jumalaanne ijankaikkisesta ijankaikkiseen! Ja sinun kunnias nimi kiitetään, joka on korotettu ylitse kaiken siunauksen ja kiitoksen."],[9,6,"Sinä olet Herra yksinäs, sinä olet luonut taivaat ja taivasten taivaat kaiken heidän sotaväkensä kanssa, maan ja kaikki, mitä sen päällä on, meret ja kaikki, mitä niissä on; ja sinä teet kaikki nämät eläväksi; ja taivaan sotajoukot kumartaen rukoilevat sinua.","Sinä olet Herra yksinäs, sinä olet luonut taivaat ja taivasten taivaat kaiken heidän sotaväkensä kanssa, maan ja kaikki, mitä sen päällä on, meret ja kaikki, mitä niissä on; ja sinä teet kaikki nämät eläväksi; ja taivaan sotajoukot kumartaen rukoilevat sinua."],[9,7,"Sinä olet Herra Jumala, joka valitsit Abramin, ja johdatit hänen Kaldean Uurista ja nimitit hänet Abrahamiksi,","Sinä olet Herra Jumala, joka valitsit Abramin, ja johdatit hänen Kaldean Uurista ja nimitit hänet Abrahamiksi,"],[9,8,"Ja löysit hänen sydämensä uskolliseksi sinun edessäs, ja teit liiton hänen kanssansa, antaakses hänen siemenellensä Kanaanealaisten, Hetiläisten, Amorilaisten, Pheresiläisten, Jebusilaisten ja Girgasilaisten maan, ja olet pitänyt sanas, sillä sinä olet vanhurskas;","Ja löysit hänen sydämensä uskolliseksi sinun edessäs, ja teit liiton hänen kanssansa, antaakses hänen siemenellensä Kanaanealaisten, Hetiläisten, Amorilaisten, Pheresiläisten, Jebusilaisten ja Girgasilaisten maan, ja olet pitänyt sanas, sillä sinä olet vanhurskas;"],[9,9,"Ja sinä näit isäimme viheliäisyyden Egyptissä, ja kuulit heidän huutonsa Punaisen meren tykönä,","Ja sinä näit isäimme viheliäisyyden Egyptissä, ja kuulit heidän huutonsa Punaisen meren tykönä,"],[9,10,"Ja teit tunnustähtejä ja ihmeitä Pharaolle, ja kaikissa hänen palvelioissansa, ja kaikessa hänen maansa kansassa; sillä sinä tiesit heidän ylpiäksi heitä vastaan; ja teit itselles nimen, niinkuin se tänäkin päivänä on.","Ja teit tunnustähtejä ja ihmeitä Pharaolle, ja kaikissa hänen palvelioissansa, ja kaikessa hänen maansa kansassa; sillä sinä tiesit heidän ylpiäksi heitä vastaan; ja teit itselles nimen, niinkuin se tänäkin päivänä on."],[9,11,"Ja sinä jaoit meren heidän edessänsä, niin että he kuivalla menivät keskitse meren; ja heidän vainoojansa heitit sinä syvyyteen, niinkuin kiven väkeviin vesiin.","Ja sinä jaoit meren heidän edessänsä, niin että he kuivalla menivät keskitse meren; ja heidän vainoojansa heitit sinä syvyyteen, niinkuin kiven väkeviin vesiin."],[9,12,"Ja päivällä sinä johdatit heitä pilven patsaalla ja yöllä tulen patsaalla, valaisten heille tietä, jota he vaelsivat.","Ja päivällä sinä johdatit heitä pilven patsaalla ja yöllä tulen patsaalla, valaisten heille tietä, jota he vaelsivat."],[9,13,"Sinä tulit Sinain vuorelta alas ja puhuit heidän kanssansa taivaasta, ja annoit heille oikiat tuomiot ja totisen lain, hyvät säädyt ja käskyt,","Sinä tulit Sinain vuorelta alas ja puhuit heidän kanssansa taivaasta, ja annoit heille oikiat tuomiot ja totisen lain, hyvät säädyt ja käskyt,"],[9,14,"Ja ilmoitit heille pyhän sabbatis, ja annoit heille käskyt, säädyt ja lain palvelias Moseksen kautta.","Ja ilmoitit heille pyhän sabbatis, ja annoit heille käskyt, säädyt ja lain palvelias Moseksen kautta."],[9,15,"Ja annoit heille leipää taivaasta, kuin he isosivat, ja annoit veden vuotaa kalliosta, kuin he janosivat; ja puhuit heille, että heidän piti menemän ja omistaman maan, jonka tähden sinä nostit kätes antaakses sen heille.","Ja annoit heille leipää taivaasta, kuin he isosivat, ja annoit veden vuotaa kalliosta, kuin he janosivat; ja puhuit heille, että heidän piti menemän ja omistaman maan, jonka tähden sinä nostit kätes antaakses sen heille."],[9,16,"Mutta he ja meidän isämme tulivat ylpeiksi ja kovakorvaisiksi, ettei he totelleet sinun käskyjäs.","Mutta he ja meidän isämme tulivat ylpeiksi ja kovakorvaisiksi, ettei he totelleet sinun käskyjäs."],[9,17,"Ja eipä he tahtoneet kuullakaan, ja ei he ajatelleet niitä ihmeitä, jotka sinä teit heidän kanssansa; vaan he tulivat uppiniskaisiksi ja asettivat päämiehen palataksensa takaperin orjuuteensa, vastahakoisuudessansa; mutta sinä Jumala olet anteeksiantaja, armollinen, laupias ja pitkämielinen, sangen suuri laupiudesta, ja et sinä heitä hyljännyt.","Ja eipä he tahtoneet kuullakaan, ja ei he ajatelleet niitä ihmeitä, jotka sinä teit heidän kanssansa; vaan he tulivat uppiniskaisiksi ja asettivat päämiehen palataksensa takaperin orjuuteensa, vastahakoisuudessansa; mutta sinä Jumala olet anteeksiantaja, armollinen, laupias ja pitkämielinen, sangen suuri laupiudesta, ja et sinä heitä hyljännyt."],[9,18,"Vaikka he tekivät valetun vasikan ja sanoivat: tämä on sinun Jumalas, joka sinun johdatti Egyptistä, ja tekivät suuren häväistyksen;","Vaikka he tekivät valetun vasikan ja sanoivat: tämä on sinun Jumalas, joka sinun johdatti Egyptistä, ja tekivät suuren häväistyksen;"],[9,19,"Et sinä kuitenkaan heitä hyljännyt korvessa, sinun suuren laupiutes tähden. Ja pilven patsas ei mennyt heiltä pois päivällä, johdattamasta heitä tiellä, eikä tulen patsas yöllä, valaisemasta heille tietä, jota he vaelsivat.","Et sinä kuitenkaan heitä hyljännyt korvessa, sinun suuren laupiutes tähden. Ja pilven patsas ei mennyt heiltä pois päivällä, johdattamasta heitä tiellä, eikä tulen patsas yöllä, valaisemasta heille tietä, jota he vaelsivat."],[9,20,"Ja sinä annoit heille hyvän henkes opettamaan heitä; et sinä myös kieltänyt mannaas heidän suustansa, ja sinä annoit heille vettä heidän janossansa.","Ja sinä annoit heille hyvän henkes opettamaan heitä; et sinä myös kieltänyt mannaas heidän suustansa, ja sinä annoit heille vettä heidän janossansa."],[9,21,"Sinä ravitsit heitä korvessa neljäkymmentä ajastaikaa, ettei heiltä mitään puuttunut; ei heidän vaatteensa vanhentuneet, eikä heidän jalkansa ajettuneet.","Sinä ravitsit heitä korvessa neljäkymmentä ajastaikaa, ettei heiltä mitään puuttunut; ei heidän vaatteensa vanhentuneet, eikä heidän jalkansa ajettuneet."],[9,22,"Sinä annoit heille valtakunnat ja kansat, ja jaoit heidät sinne ja tänne, omistamaan Sihonin maata, ja Hesbonin kuninkaan maata ja Ogin Basanin kuninkaan maata.","Sinä annoit heille valtakunnat ja kansat, ja jaoit heidät sinne ja tänne, omistamaan Sihonin maata, ja Hesbonin kuninkaan maata ja Ogin Basanin kuninkaan maata."],[9,23,"Ja sinä enensit heidän lapsensa niinkuin tähdet taivaassa, ja veit heidät siihen maahan, josta sinä heidän isillensä sanonut olit, että heidän piti sinne menemän ja omistaman.","Ja sinä enensit heidän lapsensa niinkuin tähdet taivaassa, ja veit heidät siihen maahan, josta sinä heidän isillensä sanonut olit, että heidän piti sinne menemän ja omistaman."],[9,24,"Ja lapset menivät ja omistivat maan; ja sinä nöyryytit Kanaanealaisten maan asujamet heidän edessänsä, ja annoit heitä heidän käsiinsä, niin myös heidän kuninkaansa ja maan kansat, tehdä heille oman tahtonsa perään.","Ja lapset menivät ja omistivat maan; ja sinä nöyryytit Kanaanealaisten maan asujamet heidän edessänsä, ja annoit heitä heidän käsiinsä, niin myös heidän kuninkaansa ja maan kansat, tehdä heille oman tahtonsa perään."],[9,25,"Ja he voittivat vahvat kaupungit ja lihavan maan, ja omistivat huoneet täynnä kaikkinaista viljaa, vuojonkivisiä kaivoja, viinamäkiä ja öljymäkiä ja paljon hedelmällisiä puita. Ja he söivät ja ravittiin, ja lihoivat, ja elivät herkullisesti sinun suuresta hyvyydestäs.","Ja he voittivat vahvat kaupungit ja lihavan maan, ja omistivat huoneet täynnä kaikkinaista viljaa, vuojonkivisiä kaivoja, viinamäkiä ja öljymäkiä ja paljon hedelmällisiä puita. Ja he söivät ja ravittiin, ja lihoivat, ja elivät herkullisesti sinun suuresta hyvyydestäs."],[9,26,"Mutta he tulivat tottelemattomiksi ja vastahakoisiksi sinua vastaan, ja heittivät sinun lakis selkänsä taa, ja tappoivat sinun prophetas, jotka heidän edessänsä todistivat, että he olisivat kääntyneet sinun tykös; ja he suuresti häpäisivät sinua.","Mutta he tulivat tottelemattomiksi ja vastahakoisiksi sinua vastaan, ja heittivät sinun lakis selkänsä taa, ja tappoivat sinun prophetas, jotka heidän edessänsä todistivat, että he olisivat kääntyneet sinun tykös; ja he suuresti häpäisivät sinua."],[9,27,"Sentähden sinä annoit heitä vihollistensa käsiin, jotka heitä ahdistivat. Ja he huusivat sinua ahdistuksensa aikana, ja sinä kuulit taivaasta heitä, ja laupiutes tähden annoit sinä heille pelastajat, jotka heitä auttivat vihollistensa käsistä.","Sentähden sinä annoit heitä vihollistensa käsiin, jotka heitä ahdistivat. Ja he huusivat sinua ahdistuksensa aikana, ja sinä kuulit taivaasta heitä, ja laupiutes tähden annoit sinä heille pelastajat, jotka heitä auttivat vihollistensa käsistä."],[9,28,"Mutta kun he lepoon tulivat, palasivat he pahaa tekemään sinun edessäs: niin sinä hylkäsit heitä vihollistensa käsiin, jotka heitä hallitsivat. Niin he käänsivät heitänsä ja taas huusivat sinua, ja sinä kuulit heitä taivaasta ja pelastit heitä monta aikaa, sinun suuren laupiutes tähden.","Mutta kun he lepoon tulivat, palasivat he pahaa tekemään sinun edessäs: niin sinä hylkäsit heitä vihollistensa käsiin, jotka heitä hallitsivat. Niin he käänsivät heitänsä ja taas huusivat sinua, ja sinä kuulit heitä taivaasta ja pelastit heitä monta aikaa, sinun suuren laupiutes tähden."],[9,29,"Ja sinä annoit heille tiettäväksi tehdä, että heidän piti kääntämän itsensä sinun lakis tykö; mutta he olivat ylpiät ja ei totelleet sinun käskyjäs, ja syntiä tekivät sinun tuomiotas vastaan, joita jos ihminen tekee, hän elää niissä; ja he käänsivät hartionsa ja kovensivat niskansa, ja ei totelleet.","Ja sinä annoit heille tiettäväksi tehdä, että heidän piti kääntämän itsensä sinun lakis tykö; mutta he olivat ylpiät ja ei totelleet sinun käskyjäs, ja syntiä tekivät sinun tuomiotas vastaan, joita jos ihminen tekee, hän elää niissä; ja he käänsivät hartionsa ja kovensivat niskansa, ja ei totelleet."],[9,30,"Ja sinä kärsit heitä monta ajastaikaa, ja annoit heille tehdä tiettäväksi henkes kautta sinun prophetaissas; mutta ei he ottaneet korviinsa; sentähden sinä annoit heitä maan kansain käsiin.","Ja sinä kärsit heitä monta ajastaikaa, ja annoit heille tehdä tiettäväksi henkes kautta sinun prophetaissas; mutta ei he ottaneet korviinsa; sentähden sinä annoit heitä maan kansain käsiin."],[9,31,"Mutta suuren laupiutes tähden et sinä heitä peräti teloittanut eli hyljännyt; sillä sinä olet armollinen ja laupias Jumala.","Mutta suuren laupiutes tähden et sinä heitä peräti teloittanut eli hyljännyt; sillä sinä olet armollinen ja laupias Jumala."],[9,32,"Nyt meidän Jumalamme! sinä suuri Jumala, väkevä ja peljättävä, joka pidät liiton ja laupiuden, älä vähäksy kaikkia niitä vaivoja, jotka meille ja meidän kuninkaillemme, päämiehillemme, papeillemme, prophetaillemme, isillemme ja kaikelle sinun kansalles, Assurin kuninkaan ajasta niin tähän päivään asti, tapahtuneet ovat.","Nyt meidän Jumalamme! sinä suuri Jumala, väkevä ja peljättävä, joka pidät liiton ja laupiuden, älä vähäksy kaikkia niitä vaivoja, jotka meille ja meidän kuninkaillemme, päämiehillemme, papeillemme, prophetaillemme, isillemme ja kaikelle sinun kansalles, Assurin kuninkaan ajasta niin tähän päivään asti, tapahtuneet ovat."],[9,33,"Sinä olet vanhurskas kaikissa niissä, mitkä sinä meidän päällemme olet tuonut; sillä sinä olet oikein tehnyt, mutta me olemme olleet jumalattomat.","Sinä olet vanhurskas kaikissa niissä, mitkä sinä meidän päällemme olet tuonut; sillä sinä olet oikein tehnyt, mutta me olemme olleet jumalattomat."],[9,34,"Ja meidän kuninkaamme, päämiehemme, meidän pappimme ja isämme ei ole tehneet sinun lakis jälkeen, eikä lukua pitäneet sinun käskyistäs ja todistuksistas, joita annoit heille ilmoitettaa.","Ja meidän kuninkaamme, päämiehemme, meidän pappimme ja isämme ei ole tehneet sinun lakis jälkeen, eikä lukua pitäneet sinun käskyistäs ja todistuksistas, joita annoit heille ilmoitettaa."],[9,35,"Ja ei he palvelleet sinua valtakunnassansa ja sinun suuressa hyvyydessäs, jonka sinä annoit heille, ja siinä avarassa ja lihavassa maassa, jonkas annoit heidän eteensä; ja ei he palanneet pahoista töistänsä.","Ja ei he palvelleet sinua valtakunnassansa ja sinun suuressa hyvyydessäs, jonka sinä annoit heille, ja siinä avarassa ja lihavassa maassa, jonkas annoit heidän eteensä; ja ei he palanneet pahoista töistänsä."],[9,36,"Katso, me olemme palveliat tänäpänä; ja siinä maassa, jonka annoit meidän isillemme, että he olisivat syöneet hänen hedelmiänsä ja hyvyyttänsä, katso, siinä me olemme palveliat.","Katso, me olemme palveliat tänäpänä; ja siinä maassa, jonka annoit meidän isillemme, että he olisivat syöneet hänen hedelmiänsä ja hyvyyttänsä, katso, siinä me olemme palveliat."],[9,37,"Ja se enentää tulonsa kuninkaille, jotka panit meidän päällemme meidän synteimme tähden; ja he hallitsevat meidän ruumiimme ja karjamme oman tahtonsa jälkeen, ja me olemme juuri suuressa tuskassa.","Ja se enentää tulonsa kuninkaille, jotka panit meidän päällemme meidän synteimme tähden; ja he hallitsevat meidän ruumiimme ja karjamme oman tahtonsa jälkeen, ja me olemme juuri suuressa tuskassa."],[9,38,"Ja näissä kaikissa teemme me vahvan liiton, ja kirjoitamme sen, ja annamme meidän päämiestemme, Leviläistemme sen sinetillänsä vahvistaa.","Ja näissä kaikissa teemme me vahvan liiton, ja kirjoitamme sen, ja annamme meidän päämiestemme, Leviläistemme sen sinetillänsä vahvistaa."],[10,1,"Ja ne, jotka sinettinsä painoivat, olivat Nehemia Tirsata Hakalian poika, ja Zidkia,","Ja ne, jotka sinettinsä painoivat, olivat Nehemia Tirsata Hakalian poika, ja Zidkia,"],[10,2,"Seraja, Asaria, Jeremia,","Seraja, Asaria, Jeremia,"],[10,3,"Pashur, Amaria, Malkia,","Pashur, Amaria, Malkia,"],[10,4,"Hattus, Sebania, Malluk,","Hattus, Sebania, Malluk,"],[10,5,"Harim, Meremot, Obadia,","Harim, Meremot, Obadia,"],[10,6,"Daniel, Ginnetun, Baruk,","Daniel, Ginnetun, Baruk,"],[10,7,"Mesullam, Abia, Mijamin,","Mesullam, Abia, Mijamin,"],[10,8,"Maasia, Bilgai ja Semaja: ne olivat papit.","Maasia, Bilgai ja Semaja: ne olivat papit."],[10,9,"Mutta Leviläiset olivat: Jesua Asanian poika, Binnui, Henadadin lapsista, Kadmiel,","Mutta Leviläiset olivat: Jesua Asanian poika, Binnui, Henadadin lapsista, Kadmiel,"],[10,10,"Ja heidän veljensä: Sebania, Hodia, Kelita, Pelaja, Hanan,","Ja heidän veljensä: Sebania, Hodia, Kelita, Pelaja, Hanan,"],[10,11,"Miika, Rehob, Hasabia,","Miika, Rehob, Hasabia,"],[10,12,"Sakkur, Serebia, Sebania,","Sakkur, Serebia, Sebania,"],[10,13,"Hodia, Bani ja Beninu,","Hodia, Bani ja Beninu,"],[10,14,"Kansan päämiehet olivat: Paros, Pahatmoab, Elam, Sattu, Bani,","Kansan päämiehet olivat: Paros, Pahatmoab, Elam, Sattu, Bani,"],[10,15,"Bunni, Asgad, Bebai,","Bunni, Asgad, Bebai,"],[10,16,"Adonia, Bigvai, Adin,","Adonia, Bigvai, Adin,"],[10,17,"Ater, Hiskia, Assur,","Ater, Hiskia, Assur,"],[10,18,"Hodia, Hasum, Betsai,","Hodia, Hasum, Betsai,"],[10,19,"Hariph, Anatot, Neubai,","Hariph, Anatot, Neubai,"],[10,20,"Magpias, Mesullam, Hesir,","Magpias, Mesullam, Hesir,"],[10,21,"Mesesabel, Zadok, Jaddua,","Mesesabel, Zadok, Jaddua,"],[10,22,"Pelatia, Hanan, Anaja,","Pelatia, Hanan, Anaja,"],[10,23,"Hosea, Hanania, Hasub,","Hosea, Hanania, Hasub,"],[10,24,"Halohes, Pilha, Sobek,","Halohes, Pilha, Sobek,"],[10,25,"Rehum, Hasabna, Maeseja,","Rehum, Hasabna, Maeseja,"],[10,26,"Ahia, Hanan, Anan,","Ahia, Hanan, Anan,"],[10,27,"Malluk, Harim ja Baena;","Malluk, Harim ja Baena;"],[10,28,"Ja muu kansa, papit, Leviläiset, ovenvartiat, veisaajat, Netinimit ja kaikki, jotka olivat erinneet maan kansoista Jumalan lain tykö vaimoinsa, poikainsa ja tytärtensä kanssa, ja kaikki, jotka sen ymmärtää taisivat.","Ja muu kansa, papit, Leviläiset, ovenvartiat, veisaajat, Netinimit ja kaikki, jotka olivat erinneet maan kansoista Jumalan lain tykö vaimoinsa, poikainsa ja tytärtensä kanssa, ja kaikki, jotka sen ymmärtää taisivat."],[10,29,"Ja heidän voimallisensa ottivat veljeinsä puolesta sen vastaan. Ja he tulivat vannomaan ja lupaamaan valallansa, vaeltaaksensa Jumalan laissa, joka heille oli annettu Moseksen Jumalan palvelian kautta, pitääksensä ja tehdäksensä kaikki Herran meidän Jumalamme käskyt, tuomiot ja säädyt;","Ja heidän voimallisensa ottivat veljeinsä puolesta sen vastaan. Ja he tulivat vannomaan ja lupaamaan valallansa, vaeltaaksensa Jumalan laissa, joka heille oli annettu Moseksen Jumalan palvelian kautta, pitääksensä ja tehdäksensä kaikki Herran meidän Jumalamme käskyt, tuomiot ja säädyt;"],[10,30,"Ja ettei meidän pidä antaman maan kansoille tyttäriämme, emmekä myös ota pojillemme heidän tyttäriänsä.","Ja ettei meidän pidä antaman maan kansoille tyttäriämme, emmekä myös ota pojillemme heidän tyttäriänsä."],[10,31,"Ja jos maan kansa tuo sabbatina kauppakalua ja kaikkinaista vuoden tuloa myytäväksi, niin emme ota heiltä sabbatina ja pyhäpäivänä; ja että me seitsemännen vuoden annamme olla vapaana kaikista rasituksista;","Ja jos maan kansa tuo sabbatina kauppakalua ja kaikkinaista vuoden tuloa myytäväksi, niin emme ota heiltä sabbatina ja pyhäpäivänä; ja että me seitsemännen vuoden annamme olla vapaana kaikista rasituksista;"],[10,32,"Ja panemme käskyn itse päällemme, että annamme kolmannen osan yhdestä siklistä ajastajasta Jumalamme huoneen palvelukseen:","Ja panemme käskyn itse päällemme, että annamme kolmannen osan yhdestä siklistä ajastajasta Jumalamme huoneen palvelukseen:"],[10,33,"Näkyleiväksi, alinomaiseksi ruokauhriksi, alinomaiseksi polttouhriksi, sabbatina, uusilla kuilla ja juhlapäivinä, ja pyhitetyille, ja syntiuhriksi, jolla Israel sovitetaan, ja kaikkinaiseksi tarpeeksi Jumalamme huoneessa.","Näkyleiväksi, alinomaiseksi ruokauhriksi, alinomaiseksi polttouhriksi, sabbatina, uusilla kuilla ja juhlapäivinä, ja pyhitetyille, ja syntiuhriksi, jolla Israel sovitetaan, ja kaikkinaiseksi tarpeeksi Jumalamme huoneessa."],[10,34,"Ja me heitimme arpaa pappein, Leviläisten ja kansan välillä halkouhrista, joita joka vuosi piti vietämän meidän Jumalamme huoneesen, isäimme huonetten jälkeen, määrätyillä ajoilla poltettaa Herran meidän Jumalamme alttarilla, niinkuin laissa kirjoitettu on;","Ja me heitimme arpaa pappein, Leviläisten ja kansan välillä halkouhrista, joita joka vuosi piti vietämän meidän Jumalamme huoneesen, isäimme huonetten jälkeen, määrätyillä ajoilla poltettaa Herran meidän Jumalamme alttarilla, niinkuin laissa kirjoitettu on;"],[10,35,"Ja että me joka vuosi tuomme maamme esikoisia ja kaikkinaisten puiden ensimäisiä hedelmiä Herran huoneesen;","Ja että me joka vuosi tuomme maamme esikoisia ja kaikkinaisten puiden ensimäisiä hedelmiä Herran huoneesen;"],[10,36,"Ja esikoiset pojistamme ja eläimistämme, niinkuin laissa kirjoitettu on; ja esikoiset härjistämme ja lampaistamme, että meidän pitää viemän meidän Jumalamme huoneesen papeille, jotka palvelevat Jumalamme huoneessa.","Ja esikoiset pojistamme ja eläimistämme, niinkuin laissa kirjoitettu on; ja esikoiset härjistämme ja lampaistamme, että meidän pitää viemän meidän Jumalamme huoneesen papeille, jotka palvelevat Jumalamme huoneessa."],[10,37,"Ja meidän pitää viemän taikinasta ensimäisen, ja ylennyksemme, ja kaikkinaisia puun hedelmiä, viinaa ja öljyä papeille, meidän Jumalamme huoneen kammioihin, ja Leviläisille kymmenykset meidän maastamme, että Leviläiset kaikissa kaupungeissa pitää saaman kymmenykset meidän työstämme.","Ja meidän pitää viemän taikinasta ensimäisen, ja ylennyksemme, ja kaikkinaisia puun hedelmiä, viinaa ja öljyä papeille, meidän Jumalamme huoneen kammioihin, ja Leviläisille kymmenykset meidän maastamme, että Leviläiset kaikissa kaupungeissa pitää saaman kymmenykset meidän työstämme."],[10,38,"Ja papin Aaronin pojan pitää myös saaman Leviläisten kanssa heidän kymmenyksistänsä, ja Leviläisten pitää viemän kymmenyksistänsä kymmenennen osan meidän Jumalamme huoneesen, tavarahuoneen kammioihin.","Ja papin Aaronin pojan pitää myös saaman Leviläisten kanssa heidän kymmenyksistänsä, ja Leviläisten pitää viemän kymmenyksistänsä kymmenennen osan meidän Jumalamme huoneesen, tavarahuoneen kammioihin."],[10,39,"Sillä Israelin lapset ja Levin lapset piti myös viemän jyväin, viinan ja öljyn ylennyksen kammioihin; ja siellä pitää oleman pyhät astiat, ja papit, jotka palvelevat, ja ovenvartiat, ja veisaajat. Ja emme luovu meidän Jumalamme huoneesta.","Sillä Israelin lapset ja Levin lapset piti myös viemän jyväin, viinan ja öljyn ylennyksen kammioihin; ja siellä pitää oleman pyhät astiat, ja papit, jotka palvelevat, ja ovenvartiat, ja veisaajat. Ja emme luovu meidän Jumalamme huoneesta."],[11,1,"Ja kansan päämiehet asuivat Jerusalemissa; mutta muu kansa heitti arpaa, saattaaksensa yhden kymmenestä asumaan Jerusalemiin, siihen pyhään kaupunkiin, mutta yhdeksän osaa kaupungeissa.","Ja kansan päämiehet asuivat Jerusalemissa; mutta muu kansa heitti arpaa, saattaaksensa yhden kymmenestä asumaan Jerusalemiin, siihen pyhään kaupunkiin, mutta yhdeksän osaa kaupungeissa."],[11,2,"Ja kansa siunasi kaikkia niitä miehiä, jotka mielistyivät asumaan Jerusalemissa.","Ja kansa siunasi kaikkia niitä miehiä, jotka mielistyivät asumaan Jerusalemissa."],[11,3,"Nämä ovat maakunnan päämiehet, jotka asuivat Jerusalemissa; mutta Juudan kaupungeissa asui itsekukin omaisuudessansa kaupungeissansa: Israel, papit, Leviläiset, Netinimit ja Salomon palveliain lapset.","Nämä ovat maakunnan päämiehet, jotka asuivat Jerusalemissa; mutta Juudan kaupungeissa asui itsekukin omaisuudessansa kaupungeissansa: Israel, papit, Leviläiset, Netinimit ja Salomon palveliain lapset."],[11,4,"Ja Jerusalemissa asuivat muutamat Juudan ja Benjaminin lapsista. Juudan lapsista: Ataja Ussian poika, Sakarian pojan, Amarian pojan, Sephatian pojan, Mahalaleelin pojan, Peretsen lapsista,","Ja Jerusalemissa asuivat muutamat Juudan ja Benjaminin lapsista. Juudan lapsista: Ataja Ussian poika, Sakarian pojan, Amarian pojan, Sephatian pojan, Mahalaleelin pojan, Peretsen lapsista,"],[11,5,"Ja Maeseja Barukin poika, Kolhosen pojan, Hasajan pojan, Adajan pojan, Jojaribin pojan, Sakarian pojan, Silomin pojan,","Ja Maeseja Barukin poika, Kolhosen pojan, Hasajan pojan, Adajan pojan, Jojaribin pojan, Sakarian pojan, Silomin pojan,"],[11,6,"Kaikki Peretsen lapset, jotka asuivat Jerusalemissa, neljäsataa ja kahdeksanseitsemättäkymmentä vahvaa miestä.","Kaikki Peretsen lapset, jotka asuivat Jerusalemissa, neljäsataa ja kahdeksanseitsemättäkymmentä vahvaa miestä."],[11,7,"Nämät olivat Benjaminin lapset: Sallu Mesullamin poika, Joedin pojan, Pedajan pojan, Kolajan pojan, Maasejan pojan, Itielin pojan, Jesajan pojan;","Nämät olivat Benjaminin lapset: Sallu Mesullamin poika, Joedin pojan, Pedajan pojan, Kolajan pojan, Maasejan pojan, Itielin pojan, Jesajan pojan;"],[11,8,"Ja hänen jälkeensä Gabbai, Sallai, yhdeksänsataa ja kahdeksankolmattakymmentä;","Ja hänen jälkeensä Gabbai, Sallai, yhdeksänsataa ja kahdeksankolmattakymmentä;"],[11,9,"Ja Joel Sikrin poika oli heidän esimiehensä, ja Juuda Senuan poika oli toisena kaupungin päällä.","Ja Joel Sikrin poika oli heidän esimiehensä, ja Juuda Senuan poika oli toisena kaupungin päällä."],[11,10,"Papeista, Jedaja Jojaribin poika, Jakin,","Papeista, Jedaja Jojaribin poika, Jakin,"],[11,11,"Seraja Hilkian poika, Mesullamin pojan, Zadokin pojan, Merajotin pojan, Ahitobin pojan, Jumalan huoneen päämies,","Seraja Hilkian poika, Mesullamin pojan, Zadokin pojan, Merajotin pojan, Ahitobin pojan, Jumalan huoneen päämies,"],[11,12,"Ja heidän veljiänsä, jotka huoneessa työtä tekivät, oli kahdeksansataa ja kaksikolmattakymmentä; ja Adaja Jerohamin poika, Pelalian pojan, Amsin pojan, Sakarian pojan, Pashurin pojan, Malkian pojan,","Ja heidän veljiänsä, jotka huoneessa työtä tekivät, oli kahdeksansataa ja kaksikolmattakymmentä; ja Adaja Jerohamin poika, Pelalian pojan, Amsin pojan, Sakarian pojan, Pashurin pojan, Malkian pojan,"],[11,13,"Ja hänen veljensä isäin päämiehet kaksisataa ja kaksiviidettäkymmentä; ja Amasia Asareelin poika, Ahasain pojan, Mesillemotin pojan, Immerin pojan,","Ja hänen veljensä isäin päämiehet kaksisataa ja kaksiviidettäkymmentä; ja Amasia Asareelin poika, Ahasain pojan, Mesillemotin pojan, Immerin pojan,"],[11,14,"Ja heidän veljensä, väkevät miehet, sata ja kahdeksankolmattakymmentä; ja Sabdiel Gedolimin poika oli heidän esimiehensä.","Ja heidän veljensä, väkevät miehet, sata ja kahdeksankolmattakymmentä; ja Sabdiel Gedolimin poika oli heidän esimiehensä."],[11,15,"Leviläisistä: Semaja Hasubin poika, Asrikamin pojan, Hasabian pojan, Bunnin pojan;","Leviläisistä: Semaja Hasubin poika, Asrikamin pojan, Hasabian pojan, Bunnin pojan;"],[11,16,"Ja Sabtai ja Josabad, Leviläisten päämiehistä, Jumalan huoneen ulkonaisessa työssä;","Ja Sabtai ja Josabad, Leviläisten päämiehistä, Jumalan huoneen ulkonaisessa työssä;"],[11,17,"Ja Mattania Miikan poika, Sabdin pojan, Asaphin pojan, joka oli ylimmäinen kiitosta alkamaan rukouksessa; ja Bakbukia toinen veljeinsä keskellä, ja Abda Sammuan poika, Galalin pojan, Jedutunin pojan.","Ja Mattania Miikan poika, Sabdin pojan, Asaphin pojan, joka oli ylimmäinen kiitosta alkamaan rukouksessa; ja Bakbukia toinen veljeinsä keskellä, ja Abda Sammuan poika, Galalin pojan, Jedutunin pojan."],[11,18,"Leviläisiä oli kaikkiansa pyhässä kaupungissa kaksisataa ja neljäyhdeksättäkymmentä;","Leviläisiä oli kaikkiansa pyhässä kaupungissa kaksisataa ja neljäyhdeksättäkymmentä;"],[11,19,"Ja ovenvartiat: Akkub, Talmon ja heidän veljensä, jotka porteissa vartioitsivat, sata ja kaksikahdeksattakymmentä.","Ja ovenvartiat: Akkub, Talmon ja heidän veljensä, jotka porteissa vartioitsivat, sata ja kaksikahdeksattakymmentä."],[11,20,"Mutta muut Israelista, papit ja Leviläiset olivat kaikissa Juudan kaupungeissa, jokainen omassa perinnössänsä.","Mutta muut Israelista, papit ja Leviläiset olivat kaikissa Juudan kaupungeissa, jokainen omassa perinnössänsä."],[11,21,"Ja Netinimit asuivat Ophelissa: ja Ziha ja Gispa olivat Netinimein päällä.","Ja Netinimit asuivat Ophelissa: ja Ziha ja Gispa olivat Netinimein päällä."],[11,22,"Mutta Leviläisten esimies oli Jerusalemissa, Ussi Banin poika, Hasabian pojan, Mattanian pojan, Miikan pojan; veisaajat olivat Asaphin pojista, Jumalan huoneen työn tykönä.","Mutta Leviläisten esimies oli Jerusalemissa, Ussi Banin poika, Hasabian pojan, Mattanian pojan, Miikan pojan; veisaajat olivat Asaphin pojista, Jumalan huoneen työn tykönä."],[11,23,"Sillä se oli kuninkaan käsky heille, että veisaajille piti oleman päiväinen määrä.","Sillä se oli kuninkaan käsky heille, että veisaajille piti oleman päiväinen määrä."],[11,24,"Ja Petaja Mesesabeelin poika Seran lapsista, Juudan pojan, oli kuninkaan käskyläinen kaikissa asioissa kansan tykö.","Ja Petaja Mesesabeelin poika Seran lapsista, Juudan pojan, oli kuninkaan käskyläinen kaikissa asioissa kansan tykö."],[11,25,"Ja Juudan lapset, ne jotka ulkona olivat kylissä heidän maassansa; muutamat asuivat Kirjatarbassa ja sen kylissä, ja Dibonissa ja sen kylissä, ja Kabseelissa ja sen kylissä,","Ja Juudan lapset, ne jotka ulkona olivat kylissä heidän maassansa; muutamat asuivat Kirjatarbassa ja sen kylissä, ja Dibonissa ja sen kylissä, ja Kabseelissa ja sen kylissä,"],[11,26,"ja Jesuassa, Moladassa, Betpaletissa,","ja Jesuassa, Moladassa, Betpaletissa,"],[11,27,"Ja Hasarsualissa, Bersebassa ja sen kylissä,","Ja Hasarsualissa, Bersebassa ja sen kylissä,"],[11,28,"Ja Ziklagissa ja Mekonassa ja sen kylissä,","Ja Ziklagissa ja Mekonassa ja sen kylissä,"],[11,29,"Ja Enrimmonissa, Zorgassa, Jarmutissa,","Ja Enrimmonissa, Zorgassa, Jarmutissa,"],[11,30,"Zanoassa, Adullamissa ja sen kylissä, Lakiksessa ja sen kedolla Asekassa ja sen kylissä. Ja he oleskelivat hamasta Bersebasta niin Hinnomin laaksoon asti.","Zanoassa, Adullamissa ja sen kylissä, Lakiksessa ja sen kedolla Asekassa ja sen kylissä. Ja he oleskelivat hamasta Bersebasta niin Hinnomin laaksoon asti."],[11,31,"Mutta Benjaminin lapset Gabaasta asuivat Mikmassa, Ajassa ja Betelissä ja niiden kylissä,","Mutta Benjaminin lapset Gabaasta asuivat Mikmassa, Ajassa ja Betelissä ja niiden kylissä,"],[11,32,"Anatotissa, Nobissa, Ananiassa,","Anatotissa, Nobissa, Ananiassa,"],[11,33,"Hatsorissa, Ramassa, Gittaimissa,","Hatsorissa, Ramassa, Gittaimissa,"],[11,34,"Hadidissa, Ziboimissa, Neballatissa,","Hadidissa, Ziboimissa, Neballatissa,"],[11,35,"Lodissa ja Onossa, Seppäin laaksossa.","Lodissa ja Onossa, Seppäin laaksossa."],[11,36,"Ja muutamat Leviläiset asuivat Juudan ja Benjaminin rajoilla.","Ja muutamat Leviläiset asuivat Juudan ja Benjaminin rajoilla."],[12,1,"Nämät ovat papit ja Leviläiset, jotka menivät ylös Serubbabelin Sealtielin pojan ja Jesuan kanssa: Seraja, Jeremia, Esra,","Nämät ovat papit ja Leviläiset, jotka menivät ylös Serubbabelin Sealtielin pojan ja Jesuan kanssa: Seraja, Jeremia, Esra,"],[12,2,"Amaria, Malluk, Hattus,","Amaria, Malluk, Hattus,"],[12,3,"Sekania, Rehum, Meremot,","Sekania, Rehum, Meremot,"],[12,4,"Iddo, Ginetoi, Abia,","Iddo, Ginetoi, Abia,"],[12,5,"Mijamin, Maadia, Bilga,","Mijamin, Maadia, Bilga,"],[12,6,"Semaja, Jojarib, Jedaja,","Semaja, Jojarib, Jedaja,"],[12,7,"Sallu, Amok, Hilkia ja Jedaja: nämät olivat pappein ja heidän veljeinsä päämiehet Jesuan aikana.","Sallu, Amok, Hilkia ja Jedaja: nämät olivat pappein ja heidän veljeinsä päämiehet Jesuan aikana."],[12,8,"Ja Leviläiset: Jesua, Binnui, Kadmiel, Serebia, Juuda ja Mattania kiitosvirtten päällä, hän ja hänen veljensä;","Ja Leviläiset: Jesua, Binnui, Kadmiel, Serebia, Juuda ja Mattania kiitosvirtten päällä, hän ja hänen veljensä;"],[12,9,"Bakbukia ja Unni veljinensä olivat vartiana heidän tykönänsä.","Bakbukia ja Unni veljinensä olivat vartiana heidän tykönänsä."],[12,10,"Jesua siitti Jojakimin, Jojakim siitti Eljasibin, Eljasib siitti Jojadan,","Jesua siitti Jojakimin, Jojakim siitti Eljasibin, Eljasib siitti Jojadan,"],[12,11,"Jojada siitti Jonatanin, Jonatan siitti Jadduan.","Jojada siitti Jonatanin, Jonatan siitti Jadduan."],[12,12,"Ja Jojakimin aikana olivat nämät ylimmäiset isät pappein seassa: Serajasta Meraja, Jeremiasta Hanania,","Ja Jojakimin aikana olivat nämät ylimmäiset isät pappein seassa: Serajasta Meraja, Jeremiasta Hanania,"],[12,13,"Esrasta oli Mesullam, Amariasta Johanan,","Esrasta oli Mesullam, Amariasta Johanan,"],[12,14,"Mallukista Jonatan, Sebaniasta Joseph,","Mallukista Jonatan, Sebaniasta Joseph,"],[12,15,"Harimista Adna, Merajotista Helkai,","Harimista Adna, Merajotista Helkai,"],[12,16,"Iddosta Sakaria, Ginthonista Mesullam,","Iddosta Sakaria, Ginthonista Mesullam,"],[12,17,"Abiasta Sikri, Minjaminista ja Moadiasta Piltai,","Abiasta Sikri, Minjaminista ja Moadiasta Piltai,"],[12,18,"Bilgasta Sammua, Semajasta Jonatan,","Bilgasta Sammua, Semajasta Jonatan,"],[12,19,"Jojaribista Matnai, Jedajasta Ussi,","Jojaribista Matnai, Jedajasta Ussi,"],[12,20,"Sallaista Kallai, Amakista Eber,","Sallaista Kallai, Amakista Eber,"],[12,21,"Hilkiasta Hasabia, Jedajasta Natanael.","Hilkiasta Hasabia, Jedajasta Natanael."],[12,22,"Leviläiset Eljasibin, Jojadan, Johanan ja Jadduan aikana, kirjoitetut isäin päämiehet; niin myös papit, Dariuksen Persialaisen valtakuntaan asti.","Leviläiset Eljasibin, Jojadan, Johanan ja Jadduan aikana, kirjoitetut isäin päämiehet; niin myös papit, Dariuksen Persialaisen valtakuntaan asti."],[12,23,"Levin lapset, ylimmäiset isät, ovat kirjoitetut Aikakirjaan, Johananin Eljasibin pojan aikaan asti.","Levin lapset, ylimmäiset isät, ovat kirjoitetut Aikakirjaan, Johananin Eljasibin pojan aikaan asti."],[12,24,"Ja Leviläisten päämiehet: Hasabia, Serebia ja Jesua Kadmielin poika, ja heidän veljensä heidän vieressänsä, ylistämässä ja kiittämässä, niinkuin David Jumalan mies oli käskenyt, yksi vartia toisen kohdalla.","Ja Leviläisten päämiehet: Hasabia, Serebia ja Jesua Kadmielin poika, ja heidän veljensä heidän vieressänsä, ylistämässä ja kiittämässä, niinkuin David Jumalan mies oli käskenyt, yksi vartia toisen kohdalla."],[12,25,"Mattania, Bakbukia, Obadia, Mesullam, Talmon ja Akkub olivat ovenvartiat, tavaraporttein vartioitsemisessa.","Mattania, Bakbukia, Obadia, Mesullam, Talmon ja Akkub olivat ovenvartiat, tavaraporttein vartioitsemisessa."],[12,26,"Nämät olivat Jojakimin Jesuan pojan Jotsadakin pojan aikana, ja Nehemian maanvanhimman, ja Esran papin, kirjanoppineen, aikana.","Nämät olivat Jojakimin Jesuan pojan Jotsadakin pojan aikana, ja Nehemian maanvanhimman, ja Esran papin, kirjanoppineen, aikana."],[12,27,"Ja Jerusalemin muurin vihkimiselle etsivät he Leviläisiä kaikista heidän paikoistansa, tuodaksensa heitä Jerusalemiin pitämään vihkimistä ilolla, kiitoksella, virsillä, symbaleilla, psalmeilla ja harpuilla.","Ja Jerusalemin muurin vihkimiselle etsivät he Leviläisiä kaikista heidän paikoistansa, tuodaksensa heitä Jerusalemiin pitämään vihkimistä ilolla, kiitoksella, virsillä, symbaleilla, psalmeilla ja harpuilla."],[12,28,"Ja veisaajain lapset tulivat kokoon Jerusalemin ympäristöltä ja Netophatin kylistä,","Ja veisaajain lapset tulivat kokoon Jerusalemin ympäristöltä ja Netophatin kylistä,"],[12,29,"Ja Gilgalin huoneesta, ja Gibean ja Asmavetin pelloilta; sillä veisaajat olivat rakentaneet itsellensä taloja Jerusalemin ympärillä.","Ja Gilgalin huoneesta, ja Gibean ja Asmavetin pelloilta; sillä veisaajat olivat rakentaneet itsellensä taloja Jerusalemin ympärillä."],[12,30,"Ja papit ja Leviläiset puhdistivat itsensä: he puhdistivat myös kansan ja portit ja muurit.","Ja papit ja Leviläiset puhdistivat itsensä: he puhdistivat myös kansan ja portit ja muurit."],[12,31,"Ja minä annoin Juudan päämiehet mennä ylös muurille, ja asetin kaksi suurta laulukuntaa ja juhlasaattoa muurin päälle: (yhden) oikialle puolelle Sontaporttia.","Ja minä annoin Juudan päämiehet mennä ylös muurille, ja asetin kaksi suurta laulukuntaa ja juhlasaattoa muurin päälle: (yhden) oikialle puolelle Sontaporttia."],[12,32,"Ja Hosaja ja toinen puoli Juudan päämiehistä kävivät heidän perässänsä,","Ja Hosaja ja toinen puoli Juudan päämiehistä kävivät heidän perässänsä,"],[12,33,"Ja Asaria, Esra, Mesullam,","Ja Asaria, Esra, Mesullam,"],[12,34,"Juuda, Benjamin, Semaja ja Jeremia,","Juuda, Benjamin, Semaja ja Jeremia,"],[12,35,"Ja muutamat pappein lapsista vaskitorvein kanssa: Sakaria Jonatanin poika, Semajan pojan, Mattanian pojan, Mikajan pojan, Sakkurin pojan, Asaphin pojan;","Ja muutamat pappein lapsista vaskitorvein kanssa: Sakaria Jonatanin poika, Semajan pojan, Mattanian pojan, Mikajan pojan, Sakkurin pojan, Asaphin pojan;"],[12,36,"Ja hänen veljensä Semaja, Asareel, Milalai, Gilalai, Maai, Netaneel, Juuda, Hanani, Davidin Jumalan miehen kanteleiden kanssa, ja Esra kirjanoppinut heidän edellänsä.","Ja hänen veljensä Semaja, Asareel, Milalai, Gilalai, Maai, Netaneel, Juuda, Hanani, Davidin Jumalan miehen kanteleiden kanssa, ja Esra kirjanoppinut heidän edellänsä."],[12,37,"Ja Lähdeporttia päin menivät he ylös heidän kohdallansa astuimia myöten Davidin kaupunkiin, (ja siitä) astuimilla muurein päälle, Davidin huoneesta Vesiporttiin asti itään päin.","Ja Lähdeporttia päin menivät he ylös heidän kohdallansa astuimia myöten Davidin kaupunkiin, (ja siitä) astuimilla muurein päälle, Davidin huoneesta Vesiporttiin asti itään päin."],[12,38,"Ja toinen laulukunta kävi vastaan, ja minä sen perässä, ja toinen puoli kansaa muurin päällä, Pätsitornista leviään muuriin saakka,","Ja toinen laulukunta kävi vastaan, ja minä sen perässä, ja toinen puoli kansaa muurin päällä, Pätsitornista leviään muuriin saakka,"],[12,39,"Ja Ephraimin portista, Vanhan portin ja Kalaportin ja Hananeelin tornin ja Mean tornin ohitse Lammasporttiin asti; ja seisahtivat Vankiportissa.","Ja Ephraimin portista, Vanhan portin ja Kalaportin ja Hananeelin tornin ja Mean tornin ohitse Lammasporttiin asti; ja seisahtivat Vankiportissa."],[12,40,"Ja ne kaksi kiitoskuoria seisoivat Jumalan huoneessa, ja minä ja toinen puoli ylimmäisiä minun kanssani,","Ja ne kaksi kiitoskuoria seisoivat Jumalan huoneessa, ja minä ja toinen puoli ylimmäisiä minun kanssani,"],[12,41,"Ja papit Eliakim, Maeseja, Minjamin, Mikaja, Eljoenai, Sakaria, Hanania olivat vaskitorvein kanssa,","Ja papit Eliakim, Maeseja, Minjamin, Mikaja, Eljoenai, Sakaria, Hanania olivat vaskitorvein kanssa,"],[12,42,"Ja Maeseja, Semaja, Eleatsar, Ussi, Johanan, Malkia, Elam ja Asar. Ja veisaajat veisasivat korkiasti, ja Jisrahia oli esimiehenä.","Ja Maeseja, Semaja, Eleatsar, Ussi, Johanan, Malkia, Elam ja Asar. Ja veisaajat veisasivat korkiasti, ja Jisrahia oli esimiehenä."],[12,43,"Ja he uhrasivat sinä päivänä suuret uhrit, ja olivat iloiset; sillä Jumala oli heitä iloittanut suurella ilolla, että myös vaimot ja lapsetkin iloitsivat, ja Jerusalemin ilo kuului kauvas.","Ja he uhrasivat sinä päivänä suuret uhrit, ja olivat iloiset; sillä Jumala oli heitä iloittanut suurella ilolla, että myös vaimot ja lapsetkin iloitsivat, ja Jerusalemin ilo kuului kauvas."],[12,44,"Siihen aikaan asetettiin miehet tavarakammioin päälle, joissa ylennykset, ensimäiset hedelmät ja kymmenykset olivat, joita heidän piti kokooman kaupunkein pelloista, papeille ja Leviläisille jaettaa lain jälkeen; sillä Juudalaisilla oli ilo papeista ja Leviläisistä, jotka seisoivat.","Siihen aikaan asetettiin miehet tavarakammioin päälle, joissa ylennykset, ensimäiset hedelmät ja kymmenykset olivat, joita heidän piti kokooman kaupunkein pelloista, papeille ja Leviläisille jaettaa lain jälkeen; sillä Juudalaisilla oli ilo papeista ja Leviläisistä, jotka seisoivat."],[12,45,"Ja he pitivät vaarin Jumalan vartiosta ja puhdistuksen vartiosta, niin myös veisaajista ja ovenvartioista, Davidin ja Salomon hänen poikansa käskyn jälkeen,","Ja he pitivät vaarin Jumalan vartiosta ja puhdistuksen vartiosta, niin myös veisaajista ja ovenvartioista, Davidin ja Salomon hänen poikansa käskyn jälkeen,"],[12,46,"Sillä Davidin ja Asaphin aikana olivat muinen asetetut ylimmäiset veisaajat, ja kiitosvirret ja kiitokset Jumalalle.","Sillä Davidin ja Asaphin aikana olivat muinen asetetut ylimmäiset veisaajat, ja kiitosvirret ja kiitokset Jumalalle."],[12,47,"Mutta koko Israel antoi veisaajille ja ovenvartioille osan, Serubbabelin ja Nehemian aikana, joka päivä heidän osansa; ja pyhittivät sen Leviläisille, ja Leviläiset pyhittivät Aaronin lapsille.","Mutta koko Israel antoi veisaajille ja ovenvartioille osan, Serubbabelin ja Nehemian aikana, joka päivä heidän osansa; ja pyhittivät sen Leviläisille, ja Leviläiset pyhittivät Aaronin lapsille."],[13,1,"Siihen aikaan luettiin Moseksen kirjaa kansan edessä, ja siinä löydettiin kirjoitettuna, ettei kukaan Ammonilainen ja Moabilainen saa ikänänsä tulla Jumalan seurakuntaan;","Siihen aikaan luettiin Moseksen kirjaa kansan edessä, ja siinä löydettiin kirjoitettuna, ettei kukaan Ammonilainen ja Moabilainen saa ikänänsä tulla Jumalan seurakuntaan;"],[13,2,"Sillä ei he tulleet Israelin lapsia vastaan leivällä ja vedellä, vaan palkkasivat Bileamin heitä vastaan, kiroomaan heitä; mutta meidän Jumalamme käänsi kirouksen siunaukseksi.","Sillä ei he tulleet Israelin lapsia vastaan leivällä ja vedellä, vaan palkkasivat Bileamin heitä vastaan, kiroomaan heitä; mutta meidän Jumalamme käänsi kirouksen siunaukseksi."],[13,3,"Kuin he sen lain kuulivat, niin he eroittivat kaiken sekalaisen kansan Israelista.","Kuin he sen lain kuulivat, niin he eroittivat kaiken sekalaisen kansan Israelista."],[13,4,"Ja sitä ennen oli pappi Eljasib pantu meidän Jumalan huoneen kammioin päälle, Tobian lähimmäinen;","Ja sitä ennen oli pappi Eljasib pantu meidän Jumalan huoneen kammioin päälle, Tobian lähimmäinen;"],[13,5,"Ja hän oli tehnyt hänelle suuren kammion, johon he ennen olivat panneet ruokauhria, pyhää savua, astioita ja kymmenykset jyvistä, viinasta ja öljystä, jotka olivat käsketyt annettaa Leviläisille, veisaajille ja ovenvartioille, ja pappein ylennykset.","Ja hän oli tehnyt hänelle suuren kammion, johon he ennen olivat panneet ruokauhria, pyhää savua, astioita ja kymmenykset jyvistä, viinasta ja öljystä, jotka olivat käsketyt annettaa Leviläisille, veisaajille ja ovenvartioille, ja pappein ylennykset."],[13,6,"Mutta en minä ollut silloin Jerusalemissa, kuin he kaikkia näitä tekivät; sillä Artahsastan Babelin kuninkaan toisena vuonna neljättäkymmentä tulin minä kuninkaan tykö, ja sain jonkun ajan perästä kuninkaalta luvan,","Mutta en minä ollut silloin Jerusalemissa, kuin he kaikkia näitä tekivät; sillä Artahsastan Babelin kuninkaan toisena vuonna neljättäkymmentä tulin minä kuninkaan tykö, ja sain jonkun ajan perästä kuninkaalta luvan,"],[13,7,"Ja tulin Jerusalemiin ja ymmärsin sen pahuuden, minkä Eljasib oli tehnyt Tobian tähden, että hän oli tehnyt hänelle kammion Jumalan huoneen kartanolle.","Ja tulin Jerusalemiin ja ymmärsin sen pahuuden, minkä Eljasib oli tehnyt Tobian tähden, että hän oli tehnyt hänelle kammion Jumalan huoneen kartanolle."],[13,8,"Ja minä paheksuin sitä kovin, ja heitin kaikki Tobian huoneen astiat kammiosta ulos,","Ja minä paheksuin sitä kovin, ja heitin kaikki Tobian huoneen astiat kammiosta ulos,"],[13,9,"Ja käskin puhdistaa kammiot, ja panin niihin jälleen Jumalan huoneen astiat, ruokauhrit ja pyhän savun.","Ja käskin puhdistaa kammiot, ja panin niihin jälleen Jumalan huoneen astiat, ruokauhrit ja pyhän savun."],[13,10,"Ja minä ymmärsin, ettei Leviläisille ollut annettu heidän osaansa, sentähden olivat Leviläiset ja veisaajat paenneet tekemään työtä kukin pellollensa.","Ja minä ymmärsin, ettei Leviläisille ollut annettu heidän osaansa, sentähden olivat Leviläiset ja veisaajat paenneet tekemään työtä kukin pellollensa."],[13,11,"Niin minä nuhtelin esimiehiä ja sanoin: miksi me Jumalan huoneen hylkäämme? Mutta minä kokosin heitä ja asetin siallensa.","Niin minä nuhtelin esimiehiä ja sanoin: miksi me Jumalan huoneen hylkäämme? Mutta minä kokosin heitä ja asetin siallensa."],[13,12,"Niin koko Juuda toi kymmenykset jyvistä, viinasta ja öljystä tavarakammioihin,","Niin koko Juuda toi kymmenykset jyvistä, viinasta ja öljystä tavarakammioihin,"],[13,13,"Ja minä panin sen tavaran päälle papin Selemian ja Zadokin, kirjanoppineen, ja Leviläisistä Padajan, ja heidän kätensä alla oli Hanan Sakkurin poika, Mattanian pojan: sillä he pidettiin uskollisina, ja he käskettiin jakaa veljillensä.","Ja minä panin sen tavaran päälle papin Selemian ja Zadokin, kirjanoppineen, ja Leviläisistä Padajan, ja heidän kätensä alla oli Hanan Sakkurin poika, Mattanian pojan: sillä he pidettiin uskollisina, ja he käskettiin jakaa veljillensä."],[13,14,"Minun Jumalani, muista minua sen edestä, ja älä pyyhi laupiuttani pois, minkä minä olen tehnyt Jumalani huoneelle ja hänen vartiollensa!","Minun Jumalani, muista minua sen edestä, ja älä pyyhi laupiuttani pois, minkä minä olen tehnyt Jumalani huoneelle ja hänen vartiollensa!"],[13,15,"Silloin näin minä Juudassa tallattavan viinakuurnia sabbatina ja kannettavan viljalyhteitä, ja ajettavan aaseilla viinaa, viinamarjoja, fikunia, ja kaikkinaisia kuormia, ja tuotavan Jerusalemiin sabbatin päivänä: ja minä todistin heille sinä päivänä, jona he myivät ruokakalua.","Silloin näin minä Juudassa tallattavan viinakuurnia sabbatina ja kannettavan viljalyhteitä, ja ajettavan aaseilla viinaa, viinamarjoja, fikunia, ja kaikkinaisia kuormia, ja tuotavan Jerusalemiin sabbatin päivänä: ja minä todistin heille sinä päivänä, jona he myivät ruokakalua."],[13,16,"Siinä asui myös Tyrolaisia, jotka toivat kaloja ja kaikkinaista kauppakalua, ja myivät Juudan lapsille Jerusalemissa sabbatina.","Siinä asui myös Tyrolaisia, jotka toivat kaloja ja kaikkinaista kauppakalua, ja myivät Juudan lapsille Jerusalemissa sabbatina."],[13,17,"Niin minä nuhtelin Juudan päämiehiä ja sanoin heille: mikä paha se on, jonka te teette, ja rikotte sabbatin päivän?","Niin minä nuhtelin Juudan päämiehiä ja sanoin heille: mikä paha se on, jonka te teette, ja rikotte sabbatin päivän?"],[13,18,"Eikö teidän isänne niin tehneet? ja meidän Jumalamme toi kaiken tämän onnettomuuden meidän päällemme ja tämän kaupungin päälle; ja te saatatte vielä nyt vihan enemmäksi Israelin päälle, että te rikotte sabbatin.","Eikö teidän isänne niin tehneet? ja meidän Jumalamme toi kaiken tämän onnettomuuden meidän päällemme ja tämän kaupungin päälle; ja te saatatte vielä nyt vihan enemmäksi Israelin päälle, että te rikotte sabbatin."],[13,19,"Ja kuin varjo peitti Jerusalemin portin ennen sabbatia, käskin minä ne sulkea, ja kielsin avaamasta ennenkuin jälkeen sabbatin. Ja minä panin muutamia palvelioitani portteihin, ettei yhtään kantamusta olisi tuotu sisälle sabbatin päivänä.","Ja kuin varjo peitti Jerusalemin portin ennen sabbatia, käskin minä ne sulkea, ja kielsin avaamasta ennenkuin jälkeen sabbatin. Ja minä panin muutamia palvelioitani portteihin, ettei yhtään kantamusta olisi tuotu sisälle sabbatin päivänä."],[13,20,"Niin kauppamiehet ja kaikkinaisten kaluin myyjät olivat ulkona Jerusalemista yötä kerran eli kaksi.","Niin kauppamiehet ja kaikkinaisten kaluin myyjät olivat ulkona Jerusalemista yötä kerran eli kaksi."],[13,21,"Niin minä todistin heidän edessänsä ja sanoin heille: miksi te olette yötä ympäri muurin? Jos te vielä kerran sen teette, niin minä lasken käteni teidän päällenne. Ja siitä ajasta ei he sabbatina tulleet.","Niin minä todistin heidän edessänsä ja sanoin heille: miksi te olette yötä ympäri muurin? Jos te vielä kerran sen teette, niin minä lasken käteni teidän päällenne. Ja siitä ajasta ei he sabbatina tulleet."],[13,22,"Ja minä sanoin Leviläisille, jotka puhtaat olivat: tulkaat ja ottakaat porteista vaari, ja pyhittäkäät sabbatin päivä. Minun Jumalani, muista minua senkin edestä, ja säästä minua suuren laupiutes tähden!","Ja minä sanoin Leviläisille, jotka puhtaat olivat: tulkaat ja ottakaat porteista vaari, ja pyhittäkäät sabbatin päivä. Minun Jumalani, muista minua senkin edestä, ja säästä minua suuren laupiutes tähden!"],[13,23,"Minä näin myös silloin Juudalaiset ottavan Asdodilaisia, Ammonilaisia ja Moabilaisia vaimoja.","Minä näin myös silloin Juudalaiset ottavan Asdodilaisia, Ammonilaisia ja Moabilaisia vaimoja."],[13,24,"Ja heidän lapsensa puhuivat puolittain Asdodin kielellä, ja ei taitaneet puhua Juudan kielellä, mutta jokaisen kansan kielellä.","Ja heidän lapsensa puhuivat puolittain Asdodin kielellä, ja ei taitaneet puhua Juudan kielellä, mutta jokaisen kansan kielellä."],[13,25,"Ja minä nuhtelin heitä ja kirosin heitä, ja löin muutamia miehiä, ja repelin hiuksia heidän päästänsä, ja vannotin heitä Jumalan kautta: ei teidän pidä antaman tyttäriänne heidän pojillensa, eikä ottaman heidän tyttäriänsä teidän pojillenne eli itse teillenne.","Ja minä nuhtelin heitä ja kirosin heitä, ja löin muutamia miehiä, ja repelin hiuksia heidän päästänsä, ja vannotin heitä Jumalan kautta: ei teidän pidä antaman tyttäriänne heidän pojillensa, eikä ottaman heidän tyttäriänsä teidän pojillenne eli itse teillenne."],[13,26,"Eikö Salomo Israelin kuningas niiden kanssa syntiä tehnyt? Ja ei kuitenkaan ollut yhtään kuningasta hänen vertaistansa monen pakanan seassa, ja hän oli rakas Jumalallensa, ja Jumala pani hänen koko Israelin kuninkaaksi; kuitenkin saattivat muukalaiset hänenkin syntiä tekemään.","Eikö Salomo Israelin kuningas niiden kanssa syntiä tehnyt? Ja ei kuitenkaan ollut yhtään kuningasta hänen vertaistansa monen pakanan seassa, ja hän oli rakas Jumalallensa, ja Jumala pani hänen koko Israelin kuninkaaksi; kuitenkin saattivat muukalaiset hänenkin syntiä tekemään."],[13,27,"Ettekö te sitä ole kuulleet, koska te kaikkea tätä suurta pahuutta teette, että te rikotte Jumalaamme vastaan, ottaissanne muukalaisia vaimoja?","Ettekö te sitä ole kuulleet, koska te kaikkea tätä suurta pahuutta teette, että te rikotte Jumalaamme vastaan, ottaissanne muukalaisia vaimoja?"],[13,28,"Ja yksi Jojadan lapsista, Eljasibin ylimmäisen papin poika, oli Sanballatin Horonilaisen vävy; mutta minä ajoin hänen pois minun tyköäni.","Ja yksi Jojadan lapsista, Eljasibin ylimmäisen papin poika, oli Sanballatin Horonilaisen vävy; mutta minä ajoin hänen pois minun tyköäni."],[13,29,"Muista heitä minun Jumalani, jotka turmelevat pappiuden, ja pappien ja Leviläisten liiton!","Muista heitä minun Jumalani, jotka turmelevat pappiuden, ja pappien ja Leviläisten liiton!"],[13,30,"Niin minä puhdistin heidät kaikista muukalaisista, ja asetin pappein ja Leviläisten vartiat, kunkin palvelukseensa,","Niin minä puhdistin heidät kaikista muukalaisista, ja asetin pappein ja Leviläisten vartiat, kunkin palvelukseensa,"],[13,31,"Ja uhrihalkoja määrätyillä ajoilla, ja ensimäisiä hedelmiä. Minun Jumalani, muista minua hyvyydellä!","Ja uhrihalkoja määrätyillä ajoilla, ja ensimäisiä hedelmiä. Minun Jumalani, muista minua hyvyydellä!"]]}};